import * as THREE from 'three';

/* ------------------------------------------------------------------ */
/*  math + randomness                                                  */
/* ------------------------------------------------------------------ */
export const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const smoothstep = (a, b, x) => {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));
export const TAU = Math.PI * 2;
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a);
export const randInt = (a, b) => Math.floor(rand(a, b + 1));
export const pick = arr => arr[Math.floor(Math.random() * arr.length)];

export function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function makeNoise2D(seed = 1) {
  const rnd = mulberry32(seed);
  const p = new Uint8Array(256);
  for (let i = 0; i < 256; i++) p[i] = i;
  for (let i = 255; i > 0; i--) {
    const j = Math.floor(rnd() * (i + 1));
    [p[i], p[j]] = [p[j], p[i]];
  }
  const perm = new Uint8Array(512);
  for (let i = 0; i < 512; i++) perm[i] = p[i & 255];
  const fade = t => t * t * t * (t * (t * 6 - 15) + 10);
  const grad = (h, x, y) => {
    switch (h & 3) {
      case 0: return x + y;
      case 1: return -x + y;
      case 2: return x - y;
      default: return -x - y;
    }
  };
  return function noise(x, y) {
    const X = Math.floor(x) & 255, Y = Math.floor(y) & 255;
    const xf = x - Math.floor(x), yf = y - Math.floor(y);
    const u = fade(xf), v = fade(yf);
    const aa = perm[perm[X] + Y], ab = perm[perm[X] + Y + 1];
    const ba = perm[perm[X + 1] + Y], bb = perm[perm[X + 1] + Y + 1];
    const x1 = lerp(grad(aa, xf, yf), grad(ba, xf - 1, yf), u);
    const x2 = lerp(grad(ab, xf, yf - 1), grad(bb, xf - 1, yf - 1), u);
    return lerp(x1, x2, v); // roughly -1..1
  };
}

export function fbm(noise, x, y, octaves = 4) {
  let amp = 1, freq = 1, sum = 0, norm = 0;
  for (let i = 0; i < octaves; i++) {
    sum += noise(x * freq, y * freq) * amp;
    norm += amp;
    amp *= 0.5; freq *= 2.03;
  }
  return sum / norm;
}

/* ------------------------------------------------------------------ */
/*  geometry helpers                                                   */
/* ------------------------------------------------------------------ */
export function colorize(geo, color, jitter = 0.06, rnd = Math.random) {
  const c = new THREE.Color(color);
  const pos = geo.attributes.position;
  const arr = new Float32Array(pos.count * 3);
  const vary = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const j = 1 + (rnd() - 0.5) * jitter;
    vary.setRGB(c.r * j, c.g * j, c.b * j);
    arr[i * 3] = vary.r; arr[i * 3 + 1] = vary.g; arr[i * 3 + 2] = vary.b;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(arr, 3));
  return geo;
}

/** Merge non-indexed geometries that share position/normal/color. */
export function mergeGeometries(geoms) {
  let total = 0;
  const prepared = geoms.map(g => {
    const n = g.index ? g.toNonIndexed() : g;
    total += n.attributes.position.count;
    return n;
  });
  const pos = new Float32Array(total * 3);
  const nor = new Float32Array(total * 3);
  const col = new Float32Array(total * 3);
  let o = 0;
  for (const g of prepared) {
    const p = g.attributes.position, n = g.attributes.normal, c = g.attributes.color;
    pos.set(p.array, o * 3);
    if (n) nor.set(n.array, o * 3);
    if (c) col.set(c.array, o * 3);
    else col.fill(1, o * 3, (o + p.count) * 3);
    o += p.count;
  }
  const merged = new THREE.BufferGeometry();
  merged.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  merged.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
  merged.setAttribute('color', new THREE.BufferAttribute(col, 3));
  merged.computeBoundingSphere();
  prepared.forEach((g, i) => { if (g !== geoms[i]) g.dispose(); });
  return merged;
}

export function transformed(geo, { pos = [0, 0, 0], rot = [0, 0, 0], scale = [1, 1, 1], color, jitter = 0.08 } = {}) {
  const m = new THREE.Matrix4();
  m.compose(
    new THREE.Vector3(...pos),
    new THREE.Quaternion().setFromEuler(new THREE.Euler(...rot)),
    new THREE.Vector3(...scale)
  );
  const g = geo.index ? geo.toNonIndexed() : geo.clone();
  g.applyMatrix4(m);
  if (color) colorize(g, color, jitter);
  return g;
}

/* ------------------------------------------------------------------ */
/*  procedural textures                                                */
/* ------------------------------------------------------------------ */
function canvas2d(size) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  return [c, c.getContext('2d')];
}

export function glowTexture(size = 128) {
  const [c, ctx] = canvas2d(size);
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.12, 'rgba(255,255,255,0.92)');
  g.addColorStop(0.35, 'rgba(255,255,255,0.32)');
  g.addColorStop(0.7, 'rgba(255,255,255,0.06)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function beamTexture(w = 64, h = 256) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const ctx = c.getContext('2d');
  const g = ctx.createLinearGradient(0, h, 0, 0);
  g.addColorStop(0, 'rgba(255,255,255,0.9)');
  g.addColorStop(0.25, 'rgba(255,255,255,0.25)');
  g.addColorStop(0.75, 'rgba(255,255,255,0.05)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
  const side = ctx.createLinearGradient(0, 0, w, 0);
  side.addColorStop(0, 'rgba(0,0,0,1)');
  side.addColorStop(0.5, 'rgba(0,0,0,0)');
  side.addColorStop(1, 'rgba(0,0,0,1)');
  ctx.globalCompositeOperation = 'destination-out';
  ctx.fillStyle = side;
  ctx.fillRect(0, 0, w, h);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function smokeTexture(size = 128) {
  const [c, ctx] = canvas2d(size);
  const rnd = mulberry32(7);
  for (let i = 0; i < 26; i++) {
    const x = rnd() * size, y = rnd() * size, r = 8 + rnd() * 32;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(255,255,255,${0.10 + rnd() * 0.1})`);
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function scratchTexture(size = 256) {
  const [c, ctx] = canvas2d(size);
  ctx.fillStyle = '#000'; ctx.fillRect(0, 0, size, size);
  const rnd = mulberry32(31);
  ctx.strokeStyle = 'rgba(255,255,255,0.5)';
  for (let i = 0; i < 40; i++) {
    ctx.beginPath();
    ctx.lineWidth = rnd() * 1.2;
    let x = rnd() * size, y = rnd() * size;
    ctx.moveTo(x, y);
    for (let j = 0; j < 4; j++) {
      x += (rnd() - 0.5) * 90; y += (rnd() - 0.5) * 90;
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
  const t = new THREE.CanvasTexture(c);
  return t;
}

/* ------------------------------------------------------------------ */
/*  misc                                                               */
/* ------------------------------------------------------------------ */
export function formatTime(seconds) {
  const s = Math.max(0, Math.floor(seconds));
  return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
}

export function shortestAngle(a, b) {
  let d = (b - a) % TAU;
  if (d > Math.PI) d -= TAU;
  if (d < -Math.PI) d += TAU;
  return d;
}

export const tempV = new THREE.Vector3();
export const tempV2 = new THREE.Vector3();

/* ==================================================================
   THE HOLLOW — procedural audio (no samples, all synthesized)
   ================================================================== */
import { clamp, rand } from './util.js';

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.ready = false;
    this.muted = false;
    this.danger = 0;
    this._heartTimer = 0;
    this._ambientTimer = 0;
    this._growlTimer = 6;
    this._lastScare = -10;
    this._time = 0;
    this.wolfPan = 0;
    this.wolfDist = 40;
  }

  init() {
    if (this.ctx) { this.ctx.resume?.(); return; }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const ctx = this.ctx = new AC();
    this.master = ctx.createGain();
    this.master.gain.value = 0.9;
    const limiter = ctx.createDynamicsCompressor();
    limiter.threshold.value = -10;
    limiter.knee.value = 12;
    limiter.ratio.value = 8;
    limiter.attack.value = 0.003;
    limiter.release.value = 0.25;
    this.master.connect(limiter);
    limiter.connect(ctx.destination);

    this.dry = ctx.createGain();
    this.dry.gain.value = 1;
    this.dry.connect(this.master);

    // synthetic reverb impulse
    this.reverb = ctx.createConvolver();
    this.reverb.buffer = this._impulse(2.6, 2.2);
    this.wet = ctx.createGain();
    this.wet.gain.value = 0.55;
    this.reverb.connect(this.wet);
    this.wet.connect(this.master);

    this.noise = this._noiseBuffer(2, false);
    this.brown = this._noiseBuffer(4, true);

    // simple master lowpass for the "underwater" muffling during scares
    this.ready = true;
    if (ctx.state === 'suspended') ctx.resume();
  }

  _impulse(seconds, decay) {
    const ctx = this.ctx;
    const len = Math.floor(ctx.sampleRate * seconds);
    const buf = ctx.createBuffer(2, len, ctx.sampleRate);
    for (let ch = 0; ch < 2; ch++) {
      const d = buf.getChannelData(ch);
      for (let i = 0; i < len; i++) {
        const t = i / len;
        d[i] = (Math.random() * 2 - 1) * Math.pow(1 - t, decay) * (1 - Math.exp(-i / 400));
      }
    }
    return buf;
  }

  _noiseBuffer(seconds, brown) {
    const ctx = this.ctx;
    const len = Math.floor(ctx.sampleRate * seconds);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const w = Math.random() * 2 - 1;
      if (brown) { last = (last + 0.02 * w) / 1.02; d[i] = last * 3.2; }
      else d[i] = w;
    }
    return buf;
  }

  _gain(v = 1) {
    const g = this.ctx.createGain();
    g.gain.value = v;
    return g;
  }

  _pan(pan = 0) {
    const p = this.ctx.createStereoPanner ? this.ctx.createStereoPanner() : null;
    if (p) p.pan.value = clamp(pan, -1, 1);
    return p;
  }

  _out(node, { pan = 0, wet = 0.25, dest = null } = {}) {
    let chain = node;
    const p = this._pan(pan);
    if (p) { chain.connect(p); chain = p; }
    chain.connect(dest || this.dry);
    if (wet > 0) {
      const send = this._gain(wet);
      chain.connect(send);
      send.connect(this.reverb);
    }
    return chain;
  }

  _noiseSrc(rate = 1, brown = false) {
    const src = this.ctx.createBufferSource();
    src.buffer = brown ? this.brown : this.noise;
    src.loop = true;
    src.playbackRate.value = rate;
    return src;
  }

  /* --------------------------- ambience --------------------------- */
  startAmbience() {
    if (!this.ready || this.ambient) return;
    const ctx = this.ctx;
    const g = this.ctx.createGain();
    g.gain.value = 0;
    g.gain.linearRampToValueAtTime(0.55, ctx.currentTime + 3);
    g.connect(this.master);

    // wind: brown noise, band-limited, slowly breathing
    const wind = this._noiseSrc(0.6, true);
    const wf = ctx.createBiquadFilter();
    wf.type = 'bandpass'; wf.frequency.value = 420; wf.Q.value = 0.5;
    const wg = ctx.createGain(); wg.gain.value = 0.22;
    const lfo = ctx.createOscillator(); lfo.frequency.value = 0.055;
    const lfoG = ctx.createGain(); lfoG.gain.value = 0.12;
    lfo.connect(lfoG); lfoG.connect(wg.gain);
    wind.connect(wf); wf.connect(wg); wg.connect(g);
    wind.start(); lfo.start();

    // high pine hiss
    const hiss = this._noiseSrc(1.1, false);
    const hf = ctx.createBiquadFilter(); hf.type = 'highpass'; hf.frequency.value = 2600;
    const hg = ctx.createGain(); hg.gain.value = 0.028;
    const hissLfo = ctx.createOscillator(); hissLfo.frequency.value = 0.11;
    const hissLfoG = ctx.createGain(); hissLfoG.gain.value = 0.018;
    hissLfo.connect(hissLfoG); hissLfoG.connect(hg.gain);
    hiss.connect(hf); hf.connect(hg); hg.connect(g);
    hiss.start(); hissLfo.start();

    // sub drone
    const droneG = this._gain(0.07);
    droneG.connect(g);
    [36.5, 55, 73.2].forEach((f, i) => {
      const o = ctx.createOscillator();
      o.type = 'sine'; o.frequency.value = f;
      const og = this._gain(i === 0 ? 0.9 : i === 1 ? 0.3 : 0.12);
      const slow = ctx.createOscillator(); slow.frequency.value = 0.03 + i * 0.017;
      const slowG = this._gain(f * 0.012);
      slow.connect(slowG); slowG.connect(o.frequency);
      o.connect(og); og.connect(droneG);
      o.start(); slow.start();
    });

    // distant night air tone
    const eerie = ctx.createOscillator();
    eerie.type = 'sine'; eerie.frequency.value = 174;
    const eg = this._gain(0.008);
    const elfo = ctx.createOscillator(); elfo.frequency.value = 0.07;
    const elfoG = this._gain(0.004);
    elfo.connect(elfoG); elfoG.connect(eg.gain);
    eerie.connect(eg); eg.connect(g);
    eerie.start(); elfo.start();

    this.ambient = { g, wind, hiss, droneG };
  }

  setAmbient(level) {
    if (!this.ambient) return;
    this.ambient.g.gain.setTargetAtTime(level, this.ctx.currentTime, 1.5);
  }

  scuff() {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const src = this._noiseSrc(rand(0.9, 1.15));
    const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = rand(380, 700);
    const g = this._gain(0);
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(rand(0.025, 0.05), t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.16);
    src.connect(f); f.connect(g);
    this._out(g, { pan: rand(-0.25, 0.25), wet: 0.1 });
    src.start(t, rand(0, 1)); src.stop(t + 0.2);
  }

  step(running = false) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const src = this._noiseSrc(rand(0.8, 1.2), true);
    const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = running ? 900 : 620;
    const g = this._gain(0);
    const vol = running ? rand(0.09, 0.13) : rand(0.035, 0.06);
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(vol, t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + (running ? 0.19 : 0.14));
    src.connect(f); f.connect(g);
    this._out(g, { pan: rand(-0.15, 0.15), wet: 0.12 });

    // soft debris crackle
    if (Math.random() < 0.45) {
      const c = this._noiseSrc(1.6);
      const cf = ctx.createBiquadFilter(); cf.type = 'highpass'; cf.frequency.value = 2200;
      const cg = this._gain(0);
      cg.gain.setValueAtTime(0.02, t + 0.01);
      cg.gain.exponentialRampToValueAtTime(0.0001, t + 0.07);
      c.connect(cf); cf.connect(cg);
      this._out(cg, { pan: rand(-0.5, 0.5), wet: 0.2 });
      c.start(t, rand(0, 1)); c.stop(t + 0.09);
    }
    src.start(t, rand(0, 1)); src.stop(t + 0.22);
  }

  twig() {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const src = this._noiseSrc(rand(0.8, 1.5));
    const f = ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = rand(1200, 2600); f.Q.value = 1.4;
    const g = this._gain(0);
    g.gain.setValueAtTime(0.0, t);
    g.gain.linearRampToValueAtTime(rand(0.05, 0.12), t + 0.005);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.1);
    src.connect(f); f.connect(g);
    this._out(g, { pan: rand(-0.85, 0.85), wet: 0.45 });
    src.start(t, rand(0, 1)); src.stop(t + 0.12);

    const o = ctx.createOscillator(); o.type = 'triangle'; o.frequency.value = rand(170, 300);
    const og = this._gain(0);
    og.gain.setValueAtTime(0.035, t);
    og.gain.exponentialRampToValueAtTime(0.0001, t + 0.09);
    o.connect(og); this._out(og, { pan: rand(-0.5, 0.5), wet: 0.3 });
    o.start(t); o.stop(t + 0.1);
  }

  pickup(index = 0) {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const base = 520 + (index % 6) * 60;
    [1, 2.01, 2.98].forEach((mult, i) => {
      const o = ctx.createOscillator();
      o.type = 'sine'; o.frequency.value = base * mult;
      const g = this._gain(0);
      g.gain.setValueAtTime(0, t + i * 0.012);
      g.gain.linearRampToValueAtTime(0.10 / (i + 1), t + i * 0.012 + 0.012);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.9 + i * 0.25);
      o.connect(g); this._out(g, { pan: rand(-0.25, 0.25), wet: 0.65 });
      o.start(t + i * 0.012); o.stop(t + 1.4 + i * 0.25);
    });
    // metal tick
    const src = this._noiseSrc(1.4);
    const f = ctx.createBiquadFilter(); f.type = 'highpass'; f.frequency.value = 2400;
    const g = this._gain(0);
    g.gain.setValueAtTime(0.09, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.12);
    src.connect(f); f.connect(g); this._out(g, { pan: 0, wet: 0.4 });
    src.start(t, rand(0, 1)); src.stop(t + 0.15);
  }

  /* --------------------------- wolf ------------------------------- */
  growl(intensity = 0.6, pan = this.wolfPan, dist = this.wolfDist) {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const vol = clamp(0.22 - dist * 0.0035, 0.02, 0.22) * (0.5 + intensity);
    const g = this._gain(0);
    const dur = rand(1.1, 2.2);
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(vol, t + 0.25);
    g.gain.setValueAtTime(vol, t + dur * 0.6);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 240 + intensity * 320;
    const o = ctx.createOscillator(); o.type = 'sawtooth'; o.frequency.value = 48 + Math.random() * 16;
    const lfo = ctx.createOscillator(); lfo.type = 'sine'; lfo.frequency.value = rand(17, 29);
    const lg = this._gain(9 + intensity * 10);
    lfo.connect(lg); lg.connect(o.frequency);
    const o2 = ctx.createOscillator(); o2.type = 'square'; o2.frequency.value = 96 + Math.random() * 20;
    const o2g = this._gain(0.12);
    o.connect(f); o2.connect(o2g); o2g.connect(f);
    f.connect(g);
    this._out(g, { pan, wet: 0.5, dest: null });
    o.start(t); o2.start(t); lfo.start(t);
    o.stop(t + dur); o2.stop(t + dur); lfo.stop(t + dur);

    // breath
    const b = this._noiseSrc(0.5, true);
    const bf = ctx.createBiquadFilter(); bf.type = 'bandpass'; bf.frequency.value = 500; bf.Q.value = 0.8;
    const bg = this._gain(vol * 0.4);
    b.connect(bf); bf.connect(bg); this._out(bg, { pan, wet: 0.4 });
    b.start(t); b.stop(t + dur);
  }

  snarl(pan = this.wolfPan) {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const g = this._gain(0);
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(0.22, t + 0.03);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.55);
    const o = ctx.createOscillator(); o.type = 'sawtooth'; o.frequency.setValueAtTime(160, t);
    o.frequency.exponentialRampToValueAtTime(70, t + 0.5);
    const dist = ctx.createWaveShaper();
    const curve = new Float32Array(1024);
    for (let i = 0; i < 1024; i++) { const x = (i / 511) - 1; curve[i] = Math.tanh(x * 5); }
    dist.curve = curve;
    const f = ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = 520; f.Q.value = 0.8;
    o.connect(dist); dist.connect(f); f.connect(g);
    this._out(g, { pan, wet: 0.35 });
    o.start(t); o.stop(t + 0.6);
  }

  howl(pan = 0, dist = 45) {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const vol = clamp(0.16 - dist * 0.0016, 0.02, 0.16);
    const g = this._gain(0);
    const dur = rand(2.4, 3.4);
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(vol, t + 0.4);
    g.gain.setValueAtTime(vol, t + dur * 0.55);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    const o = ctx.createOscillator(); o.type = 'sine';
    o.frequency.setValueAtTime(rand(330, 380), t);
    o.frequency.linearRampToValueAtTime(rand(430, 500), t + 0.5);
    o.frequency.linearRampToValueAtTime(rand(300, 350), t + dur * 0.8);
    o.frequency.linearRampToValueAtTime(rand(180, 220), t + dur);
    const o2 = ctx.createOscillator(); o2.type = 'triangle';
    o2.frequency.value = 2;
    const vib = this._gain(7);
    o2.connect(vib); vib.connect(o.frequency);
    const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 1600;
    o.connect(f); f.connect(g);
    this._out(g, { pan, wet: 0.85 });
    o.start(t); o2.start(t); o.stop(t + dur); o2.stop(t + dur);
  }

  wolfStep(pan = 0, dist = 20) {
    if (!this.ready || dist > 34) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const vol = clamp(0.3 - dist * 0.011, 0.015, 0.28);
    const o = ctx.createOscillator(); o.type = 'sine';
    o.frequency.setValueAtTime(72, t);
    o.frequency.exponentialRampToValueAtTime(38, t + 0.2);
    const g = this._gain(0);
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.28);
    o.connect(g); this._out(g, { pan, wet: 0.2 });
    o.start(t); o.stop(t + 0.3);
    const src = this._noiseSrc(0.7, true);
    const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 420;
    const ng = this._gain(vol * 0.5);
    ng.gain.exponentialRampToValueAtTime(0.0001, t + 0.15);
    src.connect(f); f.connect(ng); this._out(ng, { pan, wet: 0.2 });
    src.start(t); src.stop(t + 0.18);
  }

  heartbeat(strong = 1) {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const beat = (offset, gain) => {
      const o = ctx.createOscillator(); o.type = 'sine';
      o.frequency.setValueAtTime(58, t + offset);
      o.frequency.exponentialRampToValueAtTime(30, t + offset + 0.18);
      const g = this._gain(0);
      g.gain.setValueAtTime(0, t + offset);
      g.gain.linearRampToValueAtTime(0.30 * gain * strong, t + offset + 0.012);
      g.gain.exponentialRampToValueAtTime(0.0001, t + offset + 0.26);
      o.connect(g); g.connect(this.master);
      o.start(t + offset); o.stop(t + offset + 0.3);
    };
    beat(0, 1);
    beat(0.17, 0.6);
  }

  /* --------------------------- story ------------------------------ */
  crash() {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    // impact
    const o = ctx.createOscillator(); o.type = 'sine';
    o.frequency.setValueAtTime(120, t);
    o.frequency.exponentialRampToValueAtTime(28, t + 0.8);
    const og = this._gain(0);
    og.gain.setValueAtTime(0.9, t);
    og.gain.exponentialRampToValueAtTime(0.0001, t + 1.2);
    o.connect(og); og.connect(this.master);
    o.start(t); o.stop(t + 1.3);

    const src = this._noiseSrc(0.7, true);
    const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 1400;
    const g = this._gain(0);
    g.gain.setValueAtTime(0.8, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 1.1);
    src.connect(f); f.connect(g); this._out(g, { pan: 0, wet: 0.4 });
    src.start(t); src.stop(t + 1.2);

    // glass + metal
    for (let i = 0; i < 7; i++) {
      const dt = rand(0, 0.7);
      const s = this._noiseSrc(rand(1.2, 2.4));
      const hf = ctx.createBiquadFilter(); hf.type = 'highpass'; hf.frequency.value = rand(1800, 5200);
      const hg = this._gain(0);
      hg.gain.setValueAtTime(rand(0.04, 0.14), t + dt);
      hg.gain.exponentialRampToValueAtTime(0.0001, t + dt + rand(0.1, 0.4));
      s.connect(hf); hf.connect(hg); this._out(hg, { pan: rand(-1, 1), wet: 0.4 });
      s.start(t + dt, rand(0, 1)); s.stop(t + dt + 0.45);
    }
  }

  jumpscare() {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const now = ctx.currentTime;
    if (now - this._lastScare < 1.2) return;
    this._lastScare = now;

    // huge sub hit
    const boom = ctx.createOscillator(); boom.type = 'sine';
    boom.frequency.setValueAtTime(95, t);
    boom.frequency.exponentialRampToValueAtTime(24, t + 1.3);
    const bg = this._gain(0);
    bg.gain.setValueAtTime(1.0, t);
    bg.gain.exponentialRampToValueAtTime(0.0001, t + 1.7);
    boom.connect(bg); bg.connect(this.master);
    boom.start(t); boom.stop(t + 1.8);

    // distorted screech cluster
    const shaper = ctx.createWaveShaper();
    const curve = new Float32Array(2048);
    for (let i = 0; i < 2048; i++) { const x = (i / 1023.5) - 1; curve[i] = Math.tanh(x * 6); }
    shaper.curve = curve;
    const sg = this._gain(0);
    sg.gain.setValueAtTime(0.34, t);
    sg.gain.setValueAtTime(0.34, t + 1.05);
    sg.gain.exponentialRampToValueAtTime(0.0001, t + 1.9);
    shaper.connect(sg); sg.connect(this.master);
    [1340, 1600, 1815, 2210].forEach((f, i) => {
      const o = ctx.createOscillator(); o.type = i % 2 ? 'sawtooth' : 'square';
      o.frequency.setValueAtTime(f, t);
      o.frequency.exponentialRampToValueAtTime(f * rand(1.25, 1.8), t + 0.18);
      o.frequency.exponentialRampToValueAtTime(f * 0.45, t + 1.5);
      const og = this._gain(0.06);
      const det = ctx.createOscillator(); det.type = 'sine'; det.frequency.value = rand(7, 15);
      const dg = this._gain(rand(20, 60));
      det.connect(dg); dg.connect(o.frequency);
      o.connect(og); og.connect(shaper);
      o.start(t); det.start(t); o.stop(t + 1.8); det.stop(t + 1.8);
    });

    // screaming noise
    const src = this._noiseSrc(1.4);
    const bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.setValueAtTime(2600, t);
    bp.frequency.exponentialRampToValueAtTime(700, t + 1.2); bp.Q.value = 2.5;
    const ng = this._gain(0);
    ng.gain.setValueAtTime(0.36, t);
    ng.gain.setValueAtTime(0.3, t + 1.1);
    ng.gain.exponentialRampToValueAtTime(0.0001, t + 1.8);
    src.connect(bp); bp.connect(ng); this._out(ng, { pan: 0, wet: 0.6 });
    src.start(t, rand(0, 1)); src.stop(t + 1.9);

    // violin cluster swell
    [220, 277.2, 329.6, 440].forEach((f, i) => {
      const o = ctx.createOscillator(); o.type = 'sawtooth'; o.frequency.value = f * 1.02;
      const lfo = ctx.createOscillator(); lfo.frequency.value = 6 + i;
      const lg = this._gain(3);
      lfo.connect(lg); lg.connect(o.frequency);
      const g = this._gain(0);
      g.gain.setValueAtTime(0, t);
      g.gain.linearRampToValueAtTime(0.03, t + 0.08);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 1.9);
      const f2 = ctx.createBiquadFilter(); f2.type = 'lowpass'; f2.frequency.value = 1400;
      o.connect(f2); f2.connect(g); this._out(g, { pan: rand(-0.6, 0.6), wet: 0.8 });
      o.start(t); lfo.start(t); o.stop(t + 2); lfo.stop(t + 2);
    });
  }

  sting() {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    [55, 58.3, 116].forEach(f => {
      const o = ctx.createOscillator(); o.type = 'sawtooth'; o.frequency.value = f;
      const g = this._gain(0);
      g.gain.setValueAtTime(0, t);
      g.gain.linearRampToValueAtTime(0.06, t + 0.05);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 1.6);
      const flt = ctx.createBiquadFilter(); flt.type = 'lowpass'; flt.frequency.value = 300;
      o.connect(flt); flt.connect(g); this._out(g, { wet: 0.6 });
      o.start(t); o.stop(t + 1.7);
    });
  }

  carStart() {
    if (!this.ready) return;
    const ctx = this.ctx, t = ctx.currentTime;
    for (let i = 0; i < 3; i++) {
      const o = ctx.createOscillator(); o.type = 'sawtooth';
      o.frequency.setValueAtTime(28 + i * 3, t + i * 0.32);
      o.frequency.linearRampToValueAtTime(42, t + i * 0.32 + 0.28);
      const g = this._gain(0);
      g.gain.setValueAtTime(0, t + i * 0.32);
      g.gain.linearRampToValueAtTime(0.12, t + i * 0.32 + 0.04);
      g.gain.exponentialRampToValueAtTime(0.0001, t + i * 0.32 + 0.3);
      const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 280;
      o.connect(f); f.connect(g); this._out(g, { wet: 0.2 });
      o.start(t + i * 0.32); o.stop(t + i * 0.32 + 0.34);
    }
  }

  /* --------------------------- update ----------------------------- */
  update(dt, { danger = 0, wolfPan = 0, wolfDist = 40, sprinting = false } = {}) {
    if (!this.ready) return;
    this._time += dt;
    this.danger = danger;
    this.wolfPan = wolfPan;
    this.wolfDist = wolfDist;

    // heartbeat
    if (danger > 0.12) {
      this._heartTimer -= dt;
      if (this._heartTimer <= 0) {
        const interval = 1.55 - danger * 1.05;
        this._heartTimer = Math.max(0.34, interval + (Math.random() - 0.5) * 0.06);
        this.heartbeat(clamp(0.35 + danger * 0.9, 0.3, 1));
      }
    } else this._heartTimer = 0;

    // ambient growls / howls
    this._ambientTimer -= dt;
    if (this._ambientTimer <= 0) {
      this._ambientTimer = rand(16, 38);
      if (danger < 0.55 && Math.random() < 0.55) this.howl(wolfPan * 0.6, wolfDist + 25);
      else if (Math.random() < 0.5) this.growl(0.3, wolfPan, wolfDist + 8);
    }

    if (danger > 0.3) {
      this._growlTimer -= dt;
      if (this._growlTimer <= 0) {
        this._growlTimer = rand(4, 9);
        this.growl(danger, wolfPan, wolfDist);
      }
    }
  }
}

import * as THREE from 'three';
import {
  makeNoise2D, fbm, mulberry32, rand, randInt, pick, clamp, lerp, TAU,
  colorize, mergeGeometries, transformed, glowTexture, beamTexture, smokeTexture
} from './util.js';

/* ==================================================================
   WORLD — fog, pines, a dead road, a broken car, twenty lost pieces
   ================================================================== */

const PART_TYPES = [
  { name: 'WHEEL', kind: 'wheel' },
  { name: 'DISTRIBUTOR', kind: 'distributor' },
  { name: 'DOOR PANEL', kind: 'door' },
  { name: 'HEADLIGHT', kind: 'headlight' },
  { name: 'FRONT BUMPER', kind: 'bumper' },
  { name: 'BATTERY', kind: 'battery' },
  { name: 'SPARK PLUG', kind: 'sparkplug' },
  { name: 'SIDE MIRROR', kind: 'mirror' },
  { name: 'HOOD', kind: 'hood' },
  { name: 'EXHAUST PIPE', kind: 'pipe' },
  { name: 'GEARBOX', kind: 'gearbox' },
  { name: 'RADIATOR', kind: 'radiator' },
  { name: 'TAIL LIGHT', kind: 'taillight' },
  { name: 'FAN BELT', kind: 'belt' },
  { name: 'AXLE', kind: 'axle' },
  { name: 'CARBURETOR', kind: 'carb' },
  { name: 'SEAT', kind: 'seat' },
  { name: 'LICENSE PLATE', kind: 'plate' },
  { name: 'WIPER', kind: 'wiper' },
  { name: 'STEERING WHEEL', kind: 'steering' }
];

export class World {
  constructor(scene) {
    this.scene = scene;
    this.time = 0;
    this.parts = [];
    this.colliders = [];
    this.glow = glowTexture();
    this.beamTex = beamTexture();
    this.smokeTex = smokeTexture();
    this.noise = makeNoise2D(1337);
    this.jitter = makeNoise2D(991);
    this.wreckPos = new THREE.Vector3(0, 0, 0);
    this.collected = 0;
    this.trees = [];
    this.motes = null;
    this.wreckLight = null;
    this.beacon = null;
    this.wrect = new THREE.Group();
    this._buildSky();
    this._buildLights();
    this._buildTerrain();
    this._buildRoad();
    this._buildTrees();
    this._buildUndergrowth();
    this._buildWreck();
    this._buildParts();
    this._buildMotes();
    this._buildMist();
  }

  /* ------------------------------ terrain ------------------------------ */
  heightAt(x, z) {
    const base = fbm(this.noise, x * 0.016, z * 0.016, 3) * 2.4;
    const detail = fbm(this.noise, x * 0.09 + 31, z * 0.09 - 17, 2) * 0.38;
    const flatten = 1 - Math.exp(-((x * x + z * z) / 90));
    return (base + detail) * (0.25 + 0.75 * flatten);
  }

  roadPoint(t) {
    return this.roadCurve.getPointAt(clamp(t, 0, 1));
  }

  _buildSky() {
    const geo = new THREE.SphereGeometry(300, 24, 16);
    const mat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      uniforms: {
        top: { value: new THREE.Color('#010206') },
        mid: { value: new THREE.Color('#0a1210') },
        bottom: { value: new THREE.Color('#111a13') }
      },
      vertexShader: `varying vec3 vWorld; void main(){ vWorld = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `
        varying vec3 vWorld; uniform vec3 top; uniform vec3 mid; uniform vec3 bottom;
        void main(){
          float h = vWorld.y;
          vec3 c = mix(bottom, mid, smoothstep(-0.08, 0.22, h));
          c = mix(c, top, smoothstep(0.18, 0.75, h));
          gl_FragColor = vec4(c, 1.0);
        }`
    });
    const sky = new THREE.Mesh(geo, mat);
    sky.renderOrder = -10;
    this.scene.add(sky);

    // stars
    const rnd = mulberry32(44);
    const count = 520;
    const pos = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      const theta = rnd() * TAU;
      const y = 0.12 + rnd() * 0.88;
      const r = Math.sqrt(1 - y * y);
      pos[i * 3] = Math.cos(theta) * r * 260;
      pos[i * 3 + 1] = y * 260;
      pos[i * 3 + 2] = Math.sin(theta) * r * 260;
    }
    const sg = new THREE.BufferGeometry();
    sg.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    const sm = new THREE.PointsMaterial({ color: '#aab5a0', size: 0.9, sizeAttenuation: true, transparent: true, opacity: 0.65, fog: false, depthWrite: false });
    this.stars = new THREE.Points(sg, sm);
    this.scene.add(this.stars);

    // moon
    const moonPos = new THREE.Vector3(-120, 105, -190);
    const moonGlow = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glow, color: '#a9bda6', transparent: true, opacity: 0.55, fog: false, depthWrite: false, blending: THREE.AdditiveBlending }));
    moonGlow.position.copy(moonPos);
    moonGlow.scale.setScalar(95);
    this.scene.add(moonGlow);
    const moon = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glow, color: '#e3e9d2', transparent: true, opacity: 0.98, fog: false, depthWrite: false }));
    moon.position.copy(moonPos);
    moon.scale.setScalar(23);
    this.scene.add(moon);
  }

  _buildLights() {
    const hemi = new THREE.HemisphereLight('#41544d', '#080a06', 0.62);
    this.scene.add(hemi);
    const moon = new THREE.DirectionalLight('#93a9ad', 0.75);
    moon.position.set(-60, 80, -30);
    this.scene.add(moon);
    const fill = new THREE.DirectionalLight('#263833', 0.22);
    fill.position.set(40, 20, 60);
    this.scene.add(fill);
    this.scene.fog = new THREE.FogExp2('#08100d', 0.037);
  }

  _buildTerrain() {
    const size = 270, seg = 150;
    const geo = new THREE.PlaneGeometry(size, size, seg, seg);
    geo.rotateX(-Math.PI / 2);
    const pos = geo.attributes.position;
    const colors = new Float32Array(pos.count * 3);
    const soil = new THREE.Color('#1b1c13');
    const moss = new THREE.Color('#28301c');
    const dirt = new THREE.Color('#241f18');
    const c = new THREE.Color();
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i), z = pos.getZ(i);
      const y = this.heightAt(x, z);
      pos.setY(i, y);
      const n = fbm(this.noise, x * 0.06 + 5, z * 0.06 - 3, 3);
      const m = fbm(this.noise, x * 0.018 - 8, z * 0.018 + 4, 2);
      c.copy(soil).lerp(moss, clamp(0.35 + n * 0.65, 0, 1) * 0.7);
      c.lerp(dirt, clamp(m * 0.8 + 0.2, 0, 1) * 0.45);
      colors[i * 3] = c.r; colors[i * 3 + 1] = c.g; colors[i * 3 + 2] = c.b;
    }
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    geo.computeVertexNormals();
    const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 1, metalness: 0 });
    this.ground = new THREE.Mesh(geo, mat);
    this.ground.receiveShadow = false;
    this.scene.add(this.ground);

    // damp patches — faint reflective sheets
    const patchMat = new THREE.MeshStandardMaterial({ color: '#131a16', roughness: 0.18, metalness: 0.1, transparent: true, opacity: 0.55 });
    for (let i = 0; i < 26; i++) {
      const x = rand(-110, 110), z = rand(-110, 110);
      if (x * x + z * z < 100) continue;
      const g = new THREE.CircleGeometry(rand(0.6, 2.4), 9);
      g.rotateX(-Math.PI / 2);
      g.scale(1, 1, rand(0.5, 1.4));
      const m = new THREE.Mesh(g, patchMat);
      m.position.set(x, this.heightAt(x, z) + 0.03, z);
      m.rotation.y = rand(0, TAU);
      this.scene.add(m);
    }
  }

  _buildRoad() {
    const pts = [
      [-118, 108], [-96, 82], [-78, 61], [-58, 40], [-37, 22], [-17, 8],
      [0, 0], [13, -11], [25, -27], [33, -48], [34, -70], [28, -92], [18, -114]
    ];
    this.roadCurve = new THREE.CatmullRomCurve3(pts.map(([x, z]) => new THREE.Vector3(x, 0, z)));
    const N = 220;
    const positions = [], colors = [], indices = [];
    const c1 = new THREE.Color('#1e1b16'), c2 = new THREE.Color('#24221b');
    const widths = [];
    for (let i = 0; i <= N; i++) {
      const t = i / N;
      const p = this.roadCurve.getPointAt(t);
      const tan = this.roadCurve.getTangentAt(t);
      const side = new THREE.Vector3(-tan.z, 0, tan.x).normalize();
      const w = 2.9 + Math.sin(t * 17) * 0.35 + Math.sin(t * 41) * 0.18;
      widths.push(w);
      for (const s of [-1, 1]) {
        const x = p.x + side.x * w * s, z = p.z + side.z * w * s;
        positions.push(x, this.heightAt(x, z) + 0.055, z);
        const col = (i % 3 === 0) ? c2 : c1;
        colors.push(col.r, col.g, col.b);
      }
      if (i < N) {
        const a = i * 2;
        indices.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
      }
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
    geo.setIndex(indices);
    geo.computeVertexNormals();
    const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.78, metalness: 0.05 });
    this.road = new THREE.Mesh(geo, mat);
    this.scene.add(this.road);

    // faint dead centre line
    const linePos = [];
    for (let i = 0; i <= N; i += 3) {
      const t = i / N;
      const p = this.roadCurve.getPointAt(t);
      const tan = this.roadCurve.getTangentAt(t);
      const side = new THREE.Vector3(-tan.z, 0, tan.x);
      if (Math.floor(t * 40) % 2) continue;
      for (const s of [-0.055, 0.055]) {
        linePos.push(p.x + side.x * s, this.heightAt(p.x + side.x * s, p.z + side.z * s) + 0.07, p.z + side.z * s);
      }
    }
    const lg = new THREE.BufferGeometry();
    lg.setAttribute('position', new THREE.Float32BufferAttribute(linePos, 3));
    const lm = new THREE.LineBasicMaterial({ color: '#565a45', transparent: true, opacity: 0.30 });
    this.scene.add(new THREE.LineSegments(lg, lm));
  }

  /* ------------------------------ trees -------------------------------- */
  _treeTemplate(rnd, dead = false) {
    const geoms = [];
    const H = dead ? rand(9, 15) : rand(12, 20);
    const lean = rand(-0.04, 0.04);
    const baseR = rand(0.26, 0.46);
    const trunkColor = dead ? '#292521' : '#2c251d';
    const segs = 4;
    let prevY = 0, prevX = 0, prevZ = 0;
    for (let s = 0; s < segs; s++) {
      const y0 = (s / segs) * H, y1 = ((s + 1) / segs) * H;
      const r0 = baseR * (1 - s / segs * 0.82), r1 = baseR * (1 - (s + 1) / segs * 0.82);
      const offX = lean * y0 + (rnd() - 0.5) * 0.12;
      const offZ = (rnd() - 0.5) * 0.12;
      const bend = Math.atan2(offX - prevX, 0.01) * 0;
      const g = new THREE.CylinderGeometry(r1, r0, y1 - y0 + 0.12, 7, 1);
      g.translate(0, (y0 + y1) / 2, 0);
      g.rotateZ(Math.atan2(offX - prevX, y1 - y0));
      g.translate(prevX, 0, prevZ);
      geoms.push(colorize(g, trunkColor, 0.24, rnd));
      prevX += offX - prevX; prevZ += offZ;
    }

    // branch arms
    const branchCount = dead ? randInt(5, 8) : randInt(3, 6);
    for (let i = 0; i < branchCount; i++) {
      const h = H * rand(0.28, dead ? 0.9 : 0.62);
      const len = (dead ? rand(1.4, 3.6) : rand(0.8, 2.2));
      const ang = rnd() * TAU;
      const g = new THREE.CylinderGeometry(0.025, 0.085, len, 5, 1);
      g.translate(0, len / 2, 0);
      g.rotateZ(rand(0.9, 1.5));
      g.rotateY(ang);
      g.translate(prevX * (h / H), h, prevZ * (h / H));
      geoms.push(colorize(g, trunkColor, 0.2, rnd));
      if (dead && rnd() < 0.5) {
        const tw = new THREE.CylinderGeometry(0.015, 0.035, len * 0.5, 4, 1);
        tw.translate(0, len * 0.25, 0);
        tw.rotateZ(rand(0.2, 0.8));
        tw.rotateY(rnd() * TAU);
        tw.translate(0, len * 0.7, 0);
        tw.rotateY(ang); tw.translate(prevX * (h / H), h, prevZ * (h / H));
        geoms.push(colorize(tw, trunkColor, 0.2, rnd));
      }
    }

    if (!dead) {
      // roots
      for (let i = 0; i < 5; i++) {
        const g = new THREE.ConeGeometry(0.18, 0.7, 4);
        g.rotateZ(Math.PI / 2 + rand(0.1, 0.5));
        g.rotateY((i / 5) * TAU + rnd());
        g.translate(0, 0.18, 0);
        geoms.push(colorize(g, '#241f19', 0.2, rnd));
      }
      // pine canopy
      const layers = randInt(7, 10);
      const start = H * rand(0.3, 0.4);
      const span = H - start;
      const greens = ['#1a2417', '#202b18', '#182112', '#232e1a'];
      for (let i = 0; i < layers; i++) {
        const t = i / (layers - 1);
        const rad = (1 - t) * (H * 0.155) + 0.28;
        const h = (span / layers) * rand(1.5, 2.1);
        const g = new THREE.ConeGeometry(rad, h, 8, 1);
        g.rotateY(rnd() * TAU);
        g.translate(prevX * (start / H) + (rnd() - 0.5) * 0.5, start + t * span + h * 0.25, prevZ * (start / H) + (rnd() - 0.5) * 0.5);
        geoms.push(colorize(g, pick(greens), 0.28, rnd));
      }
      // crown
      const crown = new THREE.ConeGeometry(0.35, 1.8, 6);
      crown.translate(prevX, H + 0.4, prevZ);
      geoms.push(colorize(crown, '#1c2618', 0.3, rnd));
    }
    return mergeGeometries(geoms);
  }

  _buildTrees() {
    const rnd = mulberry32(2024);
    const templates = [
      this._treeTemplate(rnd, false),
      this._treeTemplate(rnd, false),
      this._treeTemplate(rnd, false),
      this._treeTemplate(rnd, true)
    ];
    const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.97, metalness: 0, flatShading: true });
    const counts = [150, 150, 150, 70];
    const dummy = new THREE.Object3D();
    const tint = new THREE.Color();
    const placed = [];

    const positions = [];
    let guard = 0;
    while (positions.length < 520 && guard++ < 9000) {
      const a = rnd() * TAU;
      const r = 9 + Math.sqrt(rnd()) * 118;
      const x = Math.cos(a) * r, z = Math.sin(a) * r;
      if (x * x + z * z > 124 * 124) continue;
      // keep the road clear
      let nearRoad = false;
      for (let i = 0; i < 14; i++) {
        const p = this.roadCurve.getPointAt(i / 13);
        if ((p.x - x) ** 2 + (p.z - z) ** 2 < 52) { nearRoad = true; break; }
      }
      if (nearRoad) continue;
      if (x * x + z * z < 11 * 11) continue;
      let ok = true;
      for (const p of placed) {
        if ((p.x - x) ** 2 + (p.z - z) ** 2 < 4.2) { ok = false; break; }
      }
      if (!ok) continue;
      positions.push([x, z]);
      placed.push({ x, z });
    }

    // distribute across templates, keeping the dead ones spread out
    const buckets = [[], [], [], []];
    positions.forEach((p, i) => buckets[i % 11 === 0 ? 3 : i % 3].push(p));

    this.treeTemplates = templates;
    buckets.forEach((list, ti) => {
      const geo = templates[ti];
      const mesh = new THREE.InstancedMesh(geo, mat, list.length);
      list.forEach(([x, z], i) => {
        const y = this.heightAt(x, z);
        const s = ti === 3 ? rand(0.8, 1.25) : rand(0.75, 1.45);
        dummy.position.set(x, y - 0.15, z);
        dummy.rotation.set(rand(-0.03, 0.03), rand(0, TAU), rand(-0.03, 0.03));
        dummy.scale.set(s * rand(0.9, 1.1), s, s * rand(0.9, 1.1));
        dummy.updateMatrix();
        mesh.setMatrixAt(i, dummy.matrix);
        const shade = rand(0.85, 1.18);
        tint.setRGB(shade, shade * rand(0.94, 1.04), shade * rand(0.92, 1.02));
        mesh.setColorAt(i, tint);
        this.colliders.push({ x, z, r: 0.42 * s });
      });
      mesh.instanceMatrix.needsUpdate = true;
      if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
      mesh.frustumCulled = true;
      this.scene.add(mesh);
    });
  }

  _buildUndergrowth() {
    const rnd = mulberry32(77);
    const dummy = new THREE.Object3D();
    const tint = new THREE.Color();

    // ferns — six bent blades
    const blades = [];
    for (let i = 0; i < 7; i++) {
      const g = new THREE.PlaneGeometry(0.09, rand(0.5, 1.1), 1, 3);
      g.translate(0, 0.4, 0);
      g.rotateX(rand(-0.5, -0.15));
      g.rotateY((i / 7) * TAU + rnd() * 0.4);
      blades.push(colorize(g, i % 2 ? '#1e2a18' : '#26331c', 0.3, rnd));
    }
    const fernGeo = mergeGeometries(blades);
    const fernMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 1, side: THREE.DoubleSide, flatShading: true });
    const ferns = new THREE.InstancedMesh(fernGeo, fernMat, 900);
    for (let i = 0; i < 900; i++) {
      const a = rnd() * TAU, r = 6 + Math.sqrt(rnd()) * 112;
      const x = Math.cos(a) * r, z = Math.sin(a) * r;
      dummy.position.set(x, this.heightAt(x, z) - 0.05, z);
      dummy.rotation.set(0, rnd() * TAU, 0);
      const s = rand(0.6, 1.4);
      dummy.scale.set(s, s * rand(0.7, 1.5), s);
      dummy.updateMatrix();
      ferns.setMatrixAt(i, dummy.matrix);
      tint.setRGB(rand(0.8, 1.2), rand(0.85, 1.25), rand(0.75, 1.1));
      ferns.setColorAt(i, tint);
    }
    ferns.instanceMatrix.needsUpdate = true;
    if (ferns.instanceColor) ferns.instanceColor.needsUpdate = true;
    this.scene.add(ferns);

    // rocks
    const rockGeo = colorize(new THREE.IcosahedronGeometry(0.55, 0), '#2c2e27', 0.35, rnd);
    const rockMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.92, flatShading: true });
    const rocks = new THREE.InstancedMesh(rockGeo, rockMat, 150);
    for (let i = 0; i < 150; i++) {
      const a = rnd() * TAU, r = 7 + Math.sqrt(rnd()) * 116;
      const x = Math.cos(a) * r, z = Math.sin(a) * r;
      dummy.position.set(x, this.heightAt(x, z) + 0.05, z);
      dummy.rotation.set(rnd(), rnd() * TAU, rnd());
      const s = rand(0.4, 1.8);
      dummy.scale.set(s * rand(0.8, 1.6), s * rand(0.5, 1), s * rand(0.8, 1.6));
      dummy.updateMatrix();
      rocks.setMatrixAt(i, dummy.matrix);
      const v = rand(0.75, 1.2);
      tint.setRGB(v, v, v * 0.95);
      rocks.setColorAt(i, tint);
    }
    rocks.instanceMatrix.needsUpdate = true;
    if (rocks.instanceColor) rocks.instanceColor.needsUpdate = true;
    this.scene.add(rocks);

    // fallen logs
    const logMat = new THREE.MeshStandardMaterial({ color: '#2a241c', roughness: 1, flatShading: true });
    for (let i = 0; i < 14; i++) {
      const a = rand(0, TAU), r = rand(14, 100);
      const x = Math.cos(a) * r, z = Math.sin(a) * r;
      const len = rand(3, 8);
      const g = new THREE.CylinderGeometry(rand(0.16, 0.32), rand(0.22, 0.4), len, 7);
      const m = new THREE.Mesh(g, logMat);
      m.position.set(x, this.heightAt(x, z) + 0.2, z);
      m.rotation.set(Math.PI / 2 + rand(-0.1, 0.1), rand(0, TAU), rand(0, TAU));
      this.scene.add(m);
      this.colliders.push({ x, z, r: 0.4 });
    }
  }

  /* ------------------------------ wreck -------------------------------- */
  _buildWreck() {
    const grp = new THREE.Group();
    grp.position.set(0, this.heightAt(0, 0), 0);
    grp.rotation.y = 0.42;
    grp.rotation.z = 0.055;
    const bodyMat = new THREE.MeshStandardMaterial({ color: '#3b2c24', roughness: 0.62, metalness: 0.55 });
    const darkMat = new THREE.MeshStandardMaterial({ color: '#17181a', roughness: 0.4, metalness: 0.7 });
    const rustMat = new THREE.MeshStandardMaterial({ color: '#3d2a1c', roughness: 0.95, metalness: 0.2 });
    const glassMat = new THREE.MeshStandardMaterial({ color: '#0b1414', roughness: 0.12, metalness: 0.4, transparent: true, opacity: 0.55 });

    const chassis = new THREE.Mesh(new THREE.BoxGeometry(1.95, 0.55, 4.25), bodyMat);
    chassis.position.y = 0.72; chassis.rotation.x = 0.025;
    grp.add(chassis);

    const hood = new THREE.Mesh(new THREE.BoxGeometry(1.85, 0.3, 1.4), bodyMat);
    hood.position.set(0, 1.02, 1.35); hood.rotation.x = -0.16;
    grp.add(hood);

    const cabin = new THREE.Mesh(new THREE.BoxGeometry(1.75, 0.72, 1.9), bodyMat);
    cabin.position.set(0, 1.3, -0.35);
    grp.add(cabin);

    const roof = new THREE.Mesh(new THREE.BoxGeometry(1.62, 0.1, 1.5), rustMat);
    roof.position.set(0, 1.68, -0.42); roof.rotation.z = 0.03;
    grp.add(roof);

    const windshield = new THREE.Mesh(new THREE.PlaneGeometry(1.5, 0.6), glassMat);
    windshield.position.set(0, 1.42, 0.62); windshield.rotation.x = -0.42;
    grp.add(windshield);

    // front crumple
    const crumple = new THREE.Mesh(new THREE.BoxGeometry(1.72, 0.5, 0.7), rustMat);
    crumple.position.set(0.05, 0.78, 2.1); crumple.rotation.set(0.24, 0.18, -0.09);
    grp.add(crumple);

    // wheels left on the car
    const wheelGeo = new THREE.TorusGeometry(0.38, 0.16, 7, 14);
    const wheelMat = new THREE.MeshStandardMaterial({ color: '#0c0c0c', roughness: 0.95 });
    const w1 = new THREE.Mesh(wheelGeo, wheelMat);
    w1.position.set(-0.96, 0.4, -1.25); w1.rotation.y = Math.PI / 2;
    grp.add(w1);
    const w2 = new THREE.Mesh(wheelGeo, wheelMat);
    w2.position.set(0.98, 0.4, -1.3); w2.rotation.set(0.2, Math.PI / 2, 0.1);
    grp.add(w2);

    // broken glass on ground
    const glassShards = new THREE.Group();
    for (let i = 0; i < 22; i++) {
      const s = new THREE.Mesh(new THREE.PlaneGeometry(rand(0.05, 0.22), rand(0.05, 0.2)), new THREE.MeshStandardMaterial({ color: '#8fa09a', roughness: 0.1, metalness: 0.5, transparent: true, opacity: 0.6, side: THREE.DoubleSide }));
      s.rotation.set(-Math.PI / 2 + rand(-0.2, 0.2), rand(0, TAU), 0);
      s.position.set(rand(-2.6, 2.6), 0.03, rand(-1.4, 2.8));
      glassShards.add(s);
    }
    grp.add(glassShards);

    // dangling headlight
    const hl = new THREE.Mesh(new THREE.SphereGeometry(0.2, 10, 8), new THREE.MeshStandardMaterial({ color: '#efe6c0', emissive: '#e8d69a', emissiveIntensity: 0.35, roughness: 0.25 }));
    hl.position.set(-0.62, 0.72, 2.42);
    hl.scale.set(1.3, 0.7, 0.5);
    grp.add(hl);
    this.wreckLight = new THREE.PointLight('#ffdca0', 2.4, 10, 2);
    this.wreckLight.position.set(-0.6, 1.1, 2.7);
    grp.add(this.wreckLight);

    // smoke
    this.smokeSprites = [];
    for (let i = 0; i < 9; i++) {
      const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.smokeTex, color: '#9aa79a', transparent: true, opacity: 0.10, depthWrite: false }));
      s.position.set(rand(-0.3, 0.3), 1.2 + i * 0.28, 1.8 + rand(-0.2, 0.2));
      s.scale.setScalar(rand(1.0, 2.2));
      s.userData = { speed: rand(0.22, 0.5), offset: rand(0, TAU), baseY: s.position.y };
      grp.add(s);
      this.smokeSprites.push(s);
    }

    this.scene.add(grp);
    this.wreck = grp;
    this.colliders.push({ x: 0.2, z: 0.4, r: 1.9 });
  }

  /* ------------------------------ parts -------------------------------- */
  _partGeometry(kind) {
    const g = [];
    const metal = '#c9b374';
    switch (kind) {
      case 'wheel':
        g.push(colorize(new THREE.TorusGeometry(0.34, 0.13, 7, 16), '#2b2b29', 0.2));
        g.push(colorize(new THREE.CylinderGeometry(0.2, 0.2, 0.17, 8), '#8f9a92', 0.1));
        break;
      case 'door':
        g.push(colorize(new THREE.BoxGeometry(1.0, 0.72, 0.09), '#4a4238', 0.14));
        g.push(colorize(new THREE.BoxGeometry(0.86, 0.34, 0.1), '#0e1415', 0.1));
        g.push(colorize(new THREE.BoxGeometry(0.1, 0.1, 0.14), '#bda56a', 0.1));
        break;
      case 'headlight':
        g.push(colorize(new THREE.SphereGeometry(0.25, 10, 8), '#e8e1bd', 0.08));
        g.push(colorize(new THREE.CylinderGeometry(0.24, 0.18, 0.18, 10), '#3b3b36', 0.1));
        break;
      case 'bumper':
        g.push(colorize(new THREE.BoxGeometry(1.4, 0.19, 0.24), '#4b4c48', 0.1));
        g.push(colorize(new THREE.BoxGeometry(0.3, 0.24, 0.26), '#2b2c2a', 0.1));
        break;
      case 'battery':
        g.push(colorize(new THREE.BoxGeometry(0.44, 0.32, 0.3), '#22282a', 0.1));
        g.push(colorize(new THREE.CylinderGeometry(0.045, 0.045, 0.1, 6), '#a8905c', 0.1));
        g.push(colorize(new THREE.CylinderGeometry(0.04, 0.04, 0.1, 6), '#8b3b2c', 0.1));
        break;
      case 'sparkplug':
        g.push(colorize(new THREE.CylinderGeometry(0.05, 0.05, 0.3, 6), '#aeb7ac', 0.1));
        g.push(colorize(new THREE.CylinderGeometry(0.07, 0.07, 0.08, 6), '#8a8f86', 0.1));
        break;
      case 'mirror':
        g.push(colorize(new THREE.BoxGeometry(0.28, 0.18, 0.08), '#3f4642', 0.1));
        g.push(colorize(new THREE.BoxGeometry(0.05, 0.22, 0.05), '#333833', 0.1));
        break;
      case 'hood':
        g.push(colorize(new THREE.BoxGeometry(1.15, 0.08, 1.0), '#40382e', 0.12));
        break;
      case 'pipe':
        g.push(colorize(new THREE.CylinderGeometry(0.075, 0.09, 0.95, 7), '#6d6f66', 0.1));
        g.push(colorize(new THREE.CylinderGeometry(0.13, 0.13, 0.12, 7), '#595b53', 0.1));
        break;
      case 'gearbox':
        g.push(colorize(new THREE.CylinderGeometry(0.19, 0.22, 0.55, 7), '#62655c', 0.1));
        g.push(colorize(new THREE.SphereGeometry(0.15, 7, 6), '#4c4f47', 0.1));
        break;
      case 'radiator':
        g.push(colorize(new THREE.BoxGeometry(0.9, 0.5, 0.09), '#3b3f3a', 0.1));
        break;
      case 'taillight':
        g.push(colorize(new THREE.BoxGeometry(0.3, 0.17, 0.1), '#8e3328', 0.1));
        break;
      case 'belt':
        g.push(colorize(new THREE.TorusGeometry(0.27, 0.045, 5, 14), '#282a27', 0.1));
        break;
      case 'axle':
        g.push(colorize(new THREE.CylinderGeometry(0.07, 0.07, 1.2, 6), '#5c5e56', 0.1));
        g.push(colorize(new THREE.CylinderGeometry(0.13, 0.13, 0.22, 6), '#3f423b', 0.1));
        break;
      case 'carb':
        g.push(colorize(new THREE.CylinderGeometry(0.19, 0.15, 0.26, 7), '#6c6a5c', 0.1));
        g.push(colorize(new THREE.CylinderGeometry(0.22, 0.22, 0.06, 7), '#8a8370', 0.1));
        break;
      case 'seat':
        g.push(colorize(new THREE.BoxGeometry(0.46, 0.16, 0.48), '#33291f', 0.1));
        g.push(colorize(new THREE.BoxGeometry(0.46, 0.6, 0.13), '#2c231b', 0.1));
        break;
      case 'plate':
        g.push(colorize(new THREE.BoxGeometry(0.55, 0.16, 0.03), '#a9a98f', 0.1));
        break;
      case 'wiper':
        g.push(colorize(new THREE.BoxGeometry(0.7, 0.04, 0.04), '#2b2d2a', 0.1));
        break;
      case 'steering':
        g.push(colorize(new THREE.TorusGeometry(0.26, 0.045, 5, 14), '#2c2a26', 0.1));
        g.push(colorize(new THREE.BoxGeometry(0.4, 0.05, 0.05), '#413d35', 0.1));
        break;
      case 'distributor':
        g.push(colorize(new THREE.CylinderGeometry(0.13, 0.16, 0.26, 7), '#525d55', 0.1));
        g.push(colorize(new THREE.CylinderGeometry(0.02, 0.02, 0.2, 4), metal, 0.1));
        break;
      default:
        g.push(colorize(new THREE.BoxGeometry(0.4, 0.3, 0.3), '#746a4d', 0.15));
    }
    return mergeGeometries(g);
  }

  _buildParts() {
    const rnd = mulberry32(88);
    const mat = new THREE.MeshStandardMaterial({
      vertexColors: true, roughness: 0.3, metalness: 0.75,
      emissive: '#8a7432', emissiveIntensity: 0.55
    });
    const positions = [];
    let guard = 0;
    while (positions.length < 20 && guard++ < 5000) {
      const a = rnd() * TAU;
      const r = 16 + Math.sqrt(rnd()) * 88;
      const x = Math.cos(a) * r, z = Math.sin(a) * r;
      if (x * x + z * z > 112 * 112) continue;
      let ok = true;
      for (const p of positions) if ((p.x - x) ** 2 + (p.z - z) ** 2 < 11 * 11) { ok = false; break; }
      if (!ok) continue;
      // not inside a tree / wreck
      for (const c of this.colliders) {
        if ((c.x - x) ** 2 + (c.z - z) ** 2 < (c.r + 1.2) ** 2) { ok = false; break; }
      }
      if (!ok) continue;
      positions.push({ x, z });
    }
    // fallback fill
    while (positions.length < 20) {
      const a = rnd() * TAU, r = 18 + rnd() * 80;
      positions.push({ x: Math.cos(a) * r, z: Math.sin(a) * r });
    }

    for (let i = 0; i < 20; i++) {
      const type = PART_TYPES[i];
      const { x, z } = positions[i];
      const y = this.heightAt(x, z);
      const grp = new THREE.Group();
      grp.position.set(x, y, z);

      const geo = this._partGeometry(type.kind);
      const mesh = new THREE.Mesh(geo, mat);
      mesh.position.y = 0.85;
      mesh.rotation.set(rnd() * 0.4, rnd() * TAU, rnd() * 0.3);
      grp.add(mesh);

      const halo = new THREE.Sprite(new THREE.SpriteMaterial({
        map: this.glow, color: '#ffe6a8', transparent: true, opacity: 0.65,
        blending: THREE.AdditiveBlending, depthWrite: false
      }));
      halo.position.y = 0.85;
      halo.scale.setScalar(1.7);
      grp.add(halo);

      const beam = new THREE.Sprite(new THREE.SpriteMaterial({
        map: this.beamTex, color: '#e8d49a', transparent: true, opacity: 0.16,
        blending: THREE.AdditiveBlending, depthWrite: false
      }));
      beam.position.y = 3.8;
      beam.scale.set(1.15, 7.5, 1);
      grp.add(beam);

      const ringGeo = new THREE.RingGeometry(0.55, 0.72, 24);
      ringGeo.rotateX(-Math.PI / 2);
      const ring = new THREE.Mesh(ringGeo, new THREE.MeshBasicMaterial({ color: '#cfbd83', transparent: true, opacity: 0.22, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide }));
      ring.position.y = 0.08;
      grp.add(ring);

      this.scene.add(grp);
      this.parts.push({ group: grp, mesh, halo, beam, ring, name: type.name, x, z, baseY: 0.85, taken: false, seed: rnd() * TAU });
    }
  }

  _buildMotes() {
    const rnd = mulberry32(12);
    const count = 340;
    const pos = new Float32Array(count * 3);
    const seeds = [];
    for (let i = 0; i < count; i++) {
      const x = rand(-80, 80), z = rand(-80, 80);
      pos[i * 3] = x;
      pos[i * 3 + 1] = this.heightAt(x, z) + rand(0.4, 6);
      pos[i * 3 + 2] = z;
      seeds.push({ y: pos[i * 3 + 1], ph: rnd() * TAU, sp: rand(0.2, 0.7) });
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    const m = new THREE.PointsMaterial({ map: this.glow, color: '#c9d6a8', size: 0.11, transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending, depthWrite: false, alphaTest: 0.01 });
    this.motes = new THREE.Points(g, m);
    this.moteSeeds = seeds;
    this.scene.add(this.motes);
  }

  _buildMist() {
    this.mist = [];
    for (let i = 0; i < 22; i++) {
      const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.smokeTex, color: '#4d6157', transparent: true, opacity: rand(0.035, 0.09), depthWrite: false }));
      const a = rand(0, TAU), r = rand(8, 60);
      s.position.set(Math.cos(a) * r, this.heightAt(Math.cos(a) * r, Math.sin(a) * r) + rand(0.8, 3.5), Math.sin(a) * r);
      s.scale.set(rand(12, 26), rand(5, 10), 1);
      s.userData = { drift: rand(-0.25, 0.25), ph: rand(0, TAU) };
      this.scene.add(s);
      this.mist.push(s);
    }
  }

  /* ------------------------------ queries ------------------------------ */
  nearestPart(pos) {
    let best = null, bestD = Infinity;
    for (const p of this.parts) {
      if (p.taken) continue;
      const d = (p.x - pos.x) ** 2 + (p.z - pos.z) ** 2;
      if (d < bestD) { bestD = d; best = p; }
    }
    return { part: best, dist: Math.sqrt(bestD) };
  }

  collect(pos, radius = 2.0) {
    for (const p of this.parts) {
      if (p.taken) continue;
      const d = (p.x - pos.x) ** 2 + (p.z - pos.z) ** 2;
      if (d < radius * radius) {
        p.taken = true;
        p.group.visible = false;
        this.collected++;
        this._pickupBurst(p);
        return p;
      }
    }
    return null;
  }

  _pickupBurst(p) {
    const count = 16;
    const geo = new THREE.BufferGeometry();
    const pos = new Float32Array(count * 3);
    const vel = [];
    for (let i = 0; i < count; i++) {
      pos[i * 3] = p.group.position.x;
      pos[i * 3 + 1] = p.group.position.y + 0.9;
      pos[i * 3 + 2] = p.group.position.z;
      vel.push(new THREE.Vector3(rand(-1, 1), rand(1, 3), rand(-1, 1)));
    }
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    const mat = new THREE.PointsMaterial({ map: this.glow, color: '#ffe8ad', size: 0.28, transparent: true, opacity: 1, blending: THREE.AdditiveBlending, depthWrite: false });
    const pts = new THREE.Points(geo, mat);
    pts.userData = { vel, life: 0 };
    this.scene.add(pts);
    (this.bursts ||= []).push(pts);
  }

  /** Collision resolve against tree trunks & wreck. */
  resolveCollision(pos, radius = 0.36) {
    for (const c of this.colliders) {
      const dx = pos.x - c.x, dz = pos.z - c.z;
      const min = c.r + radius;
      const d2 = dx * dx + dz * dz;
      if (d2 < min * min && d2 > 0.0001) {
        const d = Math.sqrt(d2);
        const push = (min - d) / d;
        pos.x += dx * push;
        pos.z += dz * push;
      }
    }
    const r = Math.hypot(pos.x, pos.z);
    if (r > 118) {
      pos.x *= 118 / r; pos.z *= 118 / r;
    }
  }

  showBeacon() {
    if (this.beacon) return;
    const g = new THREE.Group();
    const beam = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.beamTex, color: '#bcd3a0', transparent: true, opacity: 0.35, blending: THREE.AdditiveBlending, depthWrite: false }));
    beam.scale.set(3.4, 26, 1);
    beam.position.y = 13;
    g.add(beam);
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glow, color: '#cfe3af', transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending, depthWrite: false }));
    glow.scale.setScalar(7);
    glow.position.y = 1.5;
    g.add(glow);
    g.position.set(0, this.heightAt(0, 0), 0);
    this.scene.add(g);
    this.beacon = g;
  }

  repair() {
    for (const p of this.parts) p.group.visible = false;
    this.wreckLight && (this.wreckLight.intensity = 9);
  }

  /* ------------------------------ update ------------------------------- */
  update(dt, t, playerPos, lightOn) {
    this.time = t;
    this.stars.rotation.y = t * 0.004;

    if (this.motes) {
      const pos = this.motes.geometry.attributes.position;
      for (let i = 0; i < this.moteSeeds.length; i++) {
        const s = this.moteSeeds[i];
        pos.setY(i, s.y + Math.sin(t * s.sp + s.ph) * 0.7);
        pos.setX(i, pos.getX(i) + Math.sin(t * 0.12 + s.ph) * dt * 0.08);
      }
      pos.needsUpdate = true;
    }

    for (const p of this.parts) {
      if (p.taken) continue;
      const bob = Math.sin(t * 1.1 + p.seed) * 0.12;
      p.mesh.position.y = p.baseY + bob;
      p.mesh.rotation.y += dt * 0.35;
      p.mesh.rotation.z = Math.sin(t * 0.6 + p.seed) * 0.12;
      p.halo.position.y = p.baseY + bob;
      const pulse = 0.55 + Math.sin(t * 2.1 + p.seed) * 0.14;
      p.halo.material.opacity = pulse;
      p.ring.material.opacity = 0.16 + Math.sin(t * 2.1 + p.seed) * 0.06;
      p.beam.material.opacity = 0.10 + Math.sin(t * 1.5 + p.seed) * 0.035;
    }

    for (const s of this.smokeSprites) {
      s.position.y += s.userData.speed * dt;
      s.position.x += Math.sin(t * 0.5 + s.userData.offset) * dt * 0.15;
      s.material.opacity = 0.11 * (1 - (s.position.y - s.userData.baseY) / 3.0);
      s.scale.setScalar(1.2 + (s.position.y - s.userData.baseY) * 0.45);
      if (s.position.y > s.userData.baseY + 2.8) {
        s.position.y = s.userData.baseY;
        s.material.opacity = 0.11;
        s.scale.setScalar(1.2);
      }
    }
    if (this.wreckLight) {
      const flick = playerPos ? Math.max(0, 1 - playerPos.distanceTo(this.wreck.position) / 60) : 1;
      this.wreckLight.intensity = (1.4 + Math.sin(t * 13.0) * 0.25 + Math.sin(t * 31.7) * 0.15) * (0.4 + flick * 0.6);
    }
    if (this.beacon) {
      this.beacon.children[0].material.opacity = 0.28 + Math.sin(t * 1.2) * 0.12;
    }
    for (const m of this.mist) {
      m.position.x += m.userData.drift * dt;
      m.position.y += Math.sin(t * 0.13 + m.userData.ph) * dt * 0.08;
      if (m.position.x > 70) m.position.x = -70;
      if (m.position.x < -70) m.position.x = 70;
    }

    if (this.bursts) {
      for (let i = this.bursts.length - 1; i >= 0; i--) {
        const b = this.bursts[i];
        b.userData.life += dt;
        const pos = b.geometry.attributes.position;
        for (let j = 0; j < pos.count; j++) {
          const v = b.userData.vel[j];
          pos.setXYZ(j, pos.getX(j) + v.x * dt, pos.getY(j) + v.y * dt, pos.getZ(j) + v.z * dt);
          v.y -= 4.5 * dt;
        }
        pos.needsUpdate = true;
        b.material.opacity = Math.max(0, 1 - b.userData.life * 1.4);
        if (b.userData.life > 0.8) {
          this.scene.remove(b);
          b.geometry.dispose();
          b.material.dispose();
          this.bursts.splice(i, 1);
        }
      }
    }
  }
}

import * as THREE from 'three';
import { clamp, damp, lerp, rand, TAU, shortestAngle, glowTexture } from './util.js';

/* ==================================================================
   THE WOLF — a very tall thing with very little skin on its bones
   ================================================================== */

const FUR = '#151512';
const FUR_LIGHT = '#211f1a';
const BONE = '#cfc4a4';
const EYE = '#dff2b6';

function furCone(r, h, color = FUR, seg = 5) {
  const g = new THREE.ConeGeometry(r, h, seg);
  g.translate(0, h / 2, 0);
  return new THREE.Mesh(g, new THREE.MeshStandardMaterial({ color, roughness: 1, flatShading: true }));
}

/** Head that faces +Z. Re-used for the body and the close-up scare. */
export function buildWolfHead({ scare = false } = {}) {
  const head = new THREE.Group();
  const mat = (color, extra = {}) => new THREE.MeshStandardMaterial({
    color, roughness: 0.92, metalness: 0.02, flatShading: true, fog: !scare, ...extra
  });
  const dark = mat('#161513');
  const mid = mat('#211d18');
  const flesh = mat('#3a1d18', { roughness: 1 });
  const toothMat = mat(BONE, { roughness: 0.55 });
  const eyeMat = new THREE.MeshStandardMaterial({
    color: '#f5ffd2', emissive: EYE, emissiveIntensity: scare ? 2.6 : 1.9,
    roughness: 0.25, fog: !scare
  });

  // skull
  const skull = new THREE.Mesh(new THREE.SphereGeometry(0.52, 12, 10), dark);
  skull.scale.set(1.02, 0.94, 1.12);
  head.add(skull);

  // cheekbones / gaunt hollows
  for (const s of [-1, 1]) {
    const cheek = new THREE.Mesh(new THREE.SphereGeometry(0.21, 8, 7), mid);
    cheek.position.set(s * 0.28, -0.1, 0.42);
    cheek.scale.set(0.8, 0.65, 1.3);
    head.add(cheek);
    const hollow = new THREE.Mesh(new THREE.SphereGeometry(0.12, 7, 6), mat('#0c0b0a'));
    hollow.position.set(s * 0.3, -0.16, 0.5);
    hollow.scale.set(0.6, 1, 1.4);
    head.add(hollow);
  }

  // muzzle
  const muzzle = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.36, 1.06, 7, 2), mid);
  muzzle.rotation.x = Math.PI / 2;
  muzzle.position.set(0, -0.07, 0.86);
  head.add(muzzle);
  const bridge = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.16, 0.9), mid);
  bridge.position.set(0, 0.14, 0.78);
  bridge.rotation.x = -0.04;
  head.add(bridge);

  // nose
  const nose = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 7), mat('#080808', { roughness: 0.28 }));
  nose.position.set(0, 0.04, 1.38);
  nose.scale.set(1.1, 0.8, 0.8);
  head.add(nose);

  // upper teeth
  const upperTeeth = new THREE.Group();
  for (let i = 0; i < 7; i++) {
    const z = 0.58 + i * 0.12;
    for (const s of [-1, 1]) {
      const len = i < 2 ? 0.34 : i < 5 ? 0.2 : 0.13;
      const t = new THREE.Mesh(new THREE.ConeGeometry(0.035, len, 5), toothMat);
      t.position.set(s * (0.20 + (i < 4 ? 0.045 : 0)), -0.27, z);
      t.rotation.x = Math.PI;
      t.rotation.z = s * (0.06 + Math.random() * 0.08);
      upperTeeth.add(t);
    }
  }
  head.add(upperTeeth);

  // lower jaw (pivot at back of mouth)
  const jaw = new THREE.Group();
  jaw.position.set(0, -0.3, 0.36);
  head.add(jaw);
  const jawShape = new THREE.Mesh(new THREE.BoxGeometry(0.38, 0.13, 0.95), mid);
  jawShape.position.set(0, -0.04, 0.45);
  jawShape.scale.set(1, 0.9, 1);
  jaw.add(jawShape);
  const jawTip = new THREE.Mesh(new THREE.ConeGeometry(0.17, 0.35, 6), mid);
  jawTip.rotation.x = -Math.PI / 2;
  jawTip.position.set(0, -0.03, 0.98);
  jaw.add(jawTip);
  // lower teeth
  for (let i = 0; i < 6; i++) {
    const z = 0.3 + i * 0.12;
    for (const s of [-1, 1]) {
      const t = new THREE.Mesh(new THREE.ConeGeometry(0.03, i < 2 ? 0.26 : 0.15, 5), toothMat);
      t.position.set(s * (0.15 + (i < 3 ? 0.03 : 0)), 0.06, z);
      t.rotation.z = s * 0.1;
      jaw.add(t);
    }
  }
  // tongue + throat
  const tongue = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.05, 0.7), flesh);
  tongue.position.set(0, 0.02, 0.5);
  tongue.rotation.x = 0.05;
  jaw.add(tongue);
  const throat = new THREE.Mesh(new THREE.SphereGeometry(0.22, 8, 6), mat('#120706', { roughness: 0.9 }));
  throat.position.set(0, -0.12, 0.18);
  throat.scale.set(0.8, 0.6, 0.9);
  head.add(throat);
  jaw.userData.base = 0.02;

  // eyes — sunken, wet, wrong
  const eyes = [];
  for (const s of [-1, 1]) {
    const socket = new THREE.Mesh(new THREE.SphereGeometry(0.135, 8, 7), mat('#070706', { roughness: 0.8 }));
    socket.position.set(s * 0.285, 0.22, 0.66);
    head.add(socket);
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.085, 10, 8), eyeMat);
    eye.position.set(s * 0.285, 0.22, 0.74);
    eye.scale.set(1, 0.9, 0.8);
    head.add(eye);
    eyes.push(eye);
    const pupil = new THREE.Mesh(new THREE.SphereGeometry(0.034, 6, 5), mat('#d6ddb0', { emissive: '#9aa35e', emissiveIntensity: 0.25, fog: !scare }));
    pupil.position.set(s * 0.285, 0.225, 0.812);
    head.add(pupil);
    // brow
    const brow = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.4, 5), dark);
    brow.position.set(s * 0.33, 0.36, 0.66);
    brow.rotation.set(Math.PI / 2.15, 0, s * 0.5);
    head.add(brow);
  }

  // ears
  const ears = [];
  for (const s of [-1, 1]) {
    const ear = new THREE.Mesh(new THREE.ConeGeometry(0.16, 0.62, 5), mid);
    ear.position.set(s * 0.33, 0.55, -0.05);
    ear.rotation.z = -s * 0.35;
    ear.rotation.x = -0.18;
    head.add(ear);
    ears.push(ear);
  }

  // shaggy neck ruff + scars
  for (let i = 0; i < 14; i++) {
    const a = (i / 14) * TAU;
    const c = furCone(0.07 + Math.random() * 0.05, 0.35 + Math.random() * 0.35, i % 3 ? FUR : FUR_LIGHT, 5);
    c.position.set(Math.cos(a) * 0.4, Math.sin(a) * 0.34 - 0.05, -0.35 - Math.random() * 0.15);
    c.rotation.set(rand(-0.4, 0.4), rand(0, TAU), Math.PI * 0.5 + rand(-0.6, 0.6));
    head.add(c);
  }
  // scalp tufts
  for (let i = 0; i < 7; i++) {
    const c = furCone(0.06, 0.22, FUR, 4);
    c.position.set(rand(-0.25, 0.25), 0.45, rand(-0.1, 0.35));
    c.rotation.set(rand(-0.5, 0.5), rand(0, TAU), rand(-0.5, 0.5));
    head.add(c);
  }
  // scar across the muzzle
  const scar = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.02, 0.5), mat('#5a2e25', { roughness: 0.8 }));
  scar.position.set(-0.22, 0.2, 0.75);
  scar.rotation.set(0, 0.1, 0.6);
  head.add(scar);
  const scar2 = scar.clone();
  scar2.position.set(0.12, 0.27, 0.64);
  scar2.rotation.z = -0.7;
  head.add(scar2);

  head.userData = { jaw, eyes, ears, scare };
  return head;
}

export class Wolf {
  constructor(scene, world, audio) {
    this.scene = scene;
    this.world = world;
    this.audio = audio;
    this.group = new THREE.Group();
    this.group.position.set(30, 0, -35);
    scene.add(this.group);
    this.state = 'dormant';
    this.stateTime = 0;
    this.caught = false;
    this.pressure = 0;
    this.stepDist = 0;
    this.events = [];
    this.yaw = 0;
    this.speed = 0;
    this.effSpeed = 0;
    this.spawnGrace = 18;
    this.repathTimer = 0;
    this.target = new THREE.Vector3();
    this.eyeGlow = glowTexture();
    this.distToPlayer = 99;
    this.pan = 0;
    this.legPhase = 0;
    this.blinkTimer = 3;
    this.huntingTime = 0;
    this.lostTime = 0;
    this._build();
    this._hide(true);
  }

  /* --------------------------- body --------------------------- */
  _build() {
    const g = this.group;
    const mat = (color, extra = {}) => new THREE.MeshStandardMaterial({ color, roughness: 0.98, flatShading: true, ...extra });
    const dark = mat(FUR);
    const darker = mat('#0f0f0d');
    const pale = mat('#2a2822');

    // contact shadow
    const shadow = new THREE.Mesh(
      new THREE.CircleGeometry(1.9, 24),
      new THREE.MeshBasicMaterial({ color: '#000000', transparent: true, opacity: 0.42, depthWrite: false })
    );
    shadow.rotation.x = -Math.PI / 2;
    shadow.position.y = 0.04;
    shadow.scale.set(1, 1.6, 1);
    g.add(shadow);

    // body
    const body = new THREE.Mesh(new THREE.SphereGeometry(1, 12, 10), dark);
    body.scale.set(0.72, 0.62, 1.55);
    body.position.set(0, 2.35, 0.0);
    g.add(body);
    this.body = body;

    const chest = new THREE.Mesh(new THREE.SphereGeometry(1, 10, 9), dark);
    chest.scale.set(0.78, 0.72, 0.9);
    chest.position.set(0, 2.45, 0.85);
    g.add(chest);
    this.chest = chest;

    const hips = new THREE.Mesh(new THREE.SphereGeometry(1, 10, 9), dark);
    hips.scale.set(0.68, 0.6, 0.85);
    hips.position.set(0, 2.3, -0.95);
    g.add(hips);

    // ribs — pale bone pressing through the hide
    for (let i = 0; i < 5; i++) {
      const rib = new THREE.Mesh(new THREE.TorusGeometry(0.62 - i * 0.02, 0.022, 4, 12, Math.PI * 1.15), pale);
      rib.position.set(0, 2.22 + i * 0.02, 0.55 - i * 0.28);
      rib.rotation.set(0, 0, Math.PI * 0.93);
      g.add(rib);
    }

    // spine spikes
    for (let i = 0; i < 9; i++) {
      const spike = furCone(0.07, 0.28 + Math.random() * 0.16, FUR_LIGHT, 4);
      spike.position.set(rand(-0.12, 0.12), 2.82 + Math.sin(i) * 0.06, 1.0 - i * 0.24);
      spike.rotation.z = Math.PI + rand(-0.3, 0.3);
      spike.rotation.y = rand(-0.3, 0.3);
      g.add(spike);
    }
    // shoulder shag
    for (let i = 0; i < 16; i++) {
      const a = (i / 16) * TAU;
      const c = furCone(0.06 + Math.random() * 0.05, 0.3 + Math.random() * 0.3, FUR, 4);
      c.position.set(Math.cos(a) * 0.55, 2.5 + Math.sin(a) * 0.35, 1.25 + rand(-0.2, 0.2));
      c.rotation.set(rand(-0.4, 0.4), rand(0, TAU), Math.PI * 0.5 + rand(-0.5, 0.5));
      g.add(c);
    }

    // neck
    const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.52, 1.25, 7), dark);
    neck.position.set(0, 2.95, 1.45);
    neck.rotation.x = -0.62;
    g.add(neck);

    // head
    this.headRig = new THREE.Group();
    this.headRig.position.set(0, 3.32, 2.05);
    g.add(this.headRig);
    this.head = buildWolfHead();
    this.head.scale.setScalar(0.92);
    this.headRig.add(this.head);
    this.jaw = this.head.userData.jaw;

    // eye glows
    this.eyeSprites = [];
    for (const s of [-1, 1]) {
      const spr = new THREE.Sprite(new THREE.SpriteMaterial({
        map: this.eyeGlow, color: '#eaffbb', transparent: true, opacity: 0.9,
        blending: THREE.AdditiveBlending, depthWrite: false, fog: false
      }));
      spr.scale.setScalar(0.62);
      spr.position.set(s * 0.26, 0.2, 0.86);
      this.head.add(spr);
      this.eyeSprites.push(spr);
    }

    // head light — makes the face readable when it's close
    this.headLight = new THREE.PointLight('#b9d59a', 0.0, 7, 2);
    this.headLight.position.set(0, 0.1, 0.4);
    this.head.add(this.headLight);

    // legs
    this.legs = [];
    const legDefs = [
      { x: -0.55, z: 1.15, front: true },
      { x: 0.55, z: 1.15, front: true },
      { x: -0.52, z: -1.05, front: false },
      { x: 0.52, z: -1.05, front: false }
    ];
    for (const def of legDefs) {
      const hip = new THREE.Group();
      hip.position.set(def.x, 2.28, def.z);
      g.add(hip);
      const upper = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.2, 1.15, 6), dark);
      upper.position.y = -0.57;
      hip.add(upper);
      const knee = new THREE.Group();
      knee.position.y = -1.12;
      hip.add(knee);
      const lower = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.11, 1.0, 6), dark);
      lower.position.y = -0.5;
      knee.add(lower);
      const paw = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.14, 0.5), darker);
      paw.position.set(0, -1.0, 0.08);
      knee.add(paw);
      // claws
      for (let i = 0; i < 3; i++) {
        const claw = new THREE.Mesh(new THREE.ConeGeometry(0.026, 0.18, 4), mat('#b8b095', { roughness: 0.5 }));
        claw.position.set(-0.09 + i * 0.09, -1.03, 0.34);
        claw.rotation.x = Math.PI / 2.2;
        knee.add(claw);
      }
      this.legs.push({ hip, knee, def, base: def.front ? -0.08 : 0.12 });
    }

    // tail
    this.tail = [];
    let tParent = g;
    for (let i = 0; i < 5; i++) {
      const seg = new THREE.Group();
      seg.position.set(0, 2.28, -1.55 - i * 0.0001);
      if (i === 0) seg.position.y = 2.3;
      if (i > 0) seg.position.z = -0.42;
      const len = 0.55 - i * 0.06;
      const mesh = new THREE.Mesh(new THREE.CylinderGeometry(0.1 - i * 0.012, 0.14 - i * 0.012, len, 5), dark);
      mesh.rotation.x = Math.PI / 2;
      mesh.position.z = -len / 2;
      seg.add(mesh);
      tParent.add(seg);
      tParent = seg;
      this.tail.push(seg);
    }
    this.tail[0].rotation.x = 0.35;

    this.group.visible = false;
  }

  _hide(hidden) {
    this.group.visible = !hidden;
  }

  reset(playerPos, opts = {}) {
    this.caught = false;
    this.state = 'lurk';
    this.stateTime = 0;
    this.spawnGrace = opts.grace ?? 14;
    this.huntingTime = 0;
    this.lostTime = 0;
    this.legPhase = 0;
    this._hide(false);
    const angle = rand(0, TAU);
    const dist = opts.distance ?? 34;
    let x = playerPos.x + Math.cos(angle) * dist;
    let z = playerPos.z + Math.sin(angle) * dist;
    const r = Math.hypot(x, z);
    if (r > 112) { x *= 112 / r; z *= 112 / r; }
    this.group.position.set(x, this.world.heightAt(x, z), z);
    this.yaw = Math.atan2(playerPos.x - x, playerPos.z - z);
    this.group.rotation.y = this.yaw;
    this.target.copy(playerPos);
    this.state = 'lurk';
    this.lurkTimer = 6;
    this.headRig.rotation.set(0, 0, 0);
    this.group.scale.setScalar(0.001);
    this.spawnScale = 1;
  }

  startHunt(force = false) {
    if (this.state === 'caught') return;
    this.state = 'hunt';
    this.stateTime = 0;
    this.huntingTime = 0;
    this.lostTime = 0;
    this.events.push({ type: 'snarl' });
  }

  provoke(playerPos) {
    if (this.state === 'lurk' || this.state === 'prowl') {
      if (this.spawnGrace > 0 && this.state !== 'prowl') return;
      this.startHunt();
    }
  }

  get alive() { return this.state !== 'caught'; }

  /* ------------------------------------------------------------------ */
  /*  update                                                            */
  /* ------------------------------------------------------------------ */
  update(dt, player, camera, flashlightOn) {
    const p = player.position;
    this.distToPlayer = Math.hypot(p.x - this.group.position.x, p.z - this.group.position.z);
    this.stateTime += dt;
    this.spawnGrace = Math.max(0, this.spawnGrace - dt);

    if (this.spawnScale !== undefined && this.spawnScale < 1) {
      this.spawnScale = Math.min(1, this.spawnScale + dt * 0.7);
      this.group.scale.setScalar(this.spawnScale);
    }

    // relative pan for audio
    if (camera) {
      const dx = this.group.position.x - camera.position.x;
      const dz = this.group.position.z - camera.position.z;
      const right = new THREE.Vector3(1, 0, 0).applyQuaternion(camera.quaternion);
      this.pan = clamp((dx * right.x + dz * right.z) / Math.max(6, this.distToPlayer), -1, 1);
    }

    // light reaction
    let lit = false;
    if (flashlightOn && this.distToPlayer < 30) {
      const toWolf = new THREE.Vector3().subVectors(this.group.position, camera.position).normalize();
      const forward = new THREE.Vector3(0, 0, -1).applyQuaternion(camera.quaternion);
      lit = toWolf.dot(forward) > 0.86;
    }
    this.lit = lit;
    this.headLight.intensity = lerp(this.headLight.intensity, this.distToPlayer < 16 ? 1.5 : 0.0, 1 - Math.exp(-3 * dt));

    let desiredSpeed = 0;
    let facePlayer = true;

    switch (this.state) {
      case 'lurk': {
        const spd = 1.1 + this.pressure * 0.35;
        this._moveAround(p, 23 - this.pressure * 3, spd, dt);
        desiredSpeed = spd;
        if (this.stateTime > 11 + rand(0, 3) - this.pressure * 2) {
          this.state = 'prowl';
          this.stateTime = 0;
          if (Math.random() < 0.6) this.events.push({ type: 'howl' });
        }
        if (this.spawnGrace <= 0 && this.distToPlayer < 12) {
          this.startHunt();
        }
        break;
      }
      case 'prowl': {
        const spd = 2.3 + this.pressure * 0.9;
        this._moveToward(p, spd, dt, 2.4);
        desiredSpeed = spd;
        if (this.distToPlayer < 10 + this.pressure * 2) {
          this.startHunt();
          this.events.push({ type: 'howl' });
        }
        if (this.stateTime > 20) {
          this.state = 'lurk';
          this.stateTime = 0;
          this.lurkTimer = 6;
        }
        break;
      }
      case 'hunt': {
        this.huntingTime += dt;
        const base = 4.45 + this.pressure * 0.7 + Math.min(1.9, this.huntingTime * 0.28);
        let spd = base;
        if (lit && this.distToPlayer > 3.5) spd *= 0.58;
        if (this.distToPlayer < 6) spd *= 1.06;
        this._moveToward(p, spd, dt, 0.6);
        desiredSpeed = spd;
        this.lostTime = this.distToPlayer > 34 ? this.lostTime + dt : 0;
        if (this.distToPlayer < 2.2) {
          this._catch(p);
        } else if (this.lostTime > 4 || this.huntingTime > 24) {
          this.state = 'retreat';
          this.stateTime = 0;
          this.events.push({ type: 'howl' });
        }
        break;
      }
      case 'retreat': {
        const away = new THREE.Vector3(p.x - this.group.position.x, 0, p.z - this.group.position.z).normalize().multiplyScalar(-1);
        const t = new THREE.Vector3(this.group.position.x + away.x * 30, 0, this.group.position.z + away.z * 30);
        this._moveToward(t, 7.2, dt, 2.0);
        desiredSpeed = 7.2;
        if (this.stateTime > 4.5) {
          this.state = 'lurk';
          this.stateTime = 0;
          this.spawnGrace = 5;
          this._teleportAround(p, 30, 45);
        }
        break;
      }
      case 'caught': {
        desiredSpeed = 0;
        break;
      }
      default: break;
    }

    // never stray too far for too long — quietly reposition behind the fog
    if (this.distToPlayer > 78 && this.state !== 'caught') {
      this._teleportAround(p, 30, 42);
    }

    this._animate(dt, player, camera, desiredSpeed, facePlayer);
  }

  _findNearby(x, z) {
    return this.world.colliders.filter(c => (c.x - x) ** 2 + (c.z - z) ** 2 < 16);
  }

  _moveToward(target, speed, dt, stopDist = 1.6) {
    const pos = this.group.position;
    const dx = target.x - pos.x, dz = target.z - pos.z;
    const dist = Math.hypot(dx, dz);
    if (dist > stopDist) {
      let mx = dx / dist, mz = dz / dist;
      // steer around trunks
      for (const c of this._findNearby(pos.x, pos.z)) {
        const ddx = pos.x - c.x, ddz = pos.z - c.z;
        const d = Math.hypot(ddx, ddz);
        if (d < c.r + 1.5 && d > 0.001) {
          const f = (c.r + 1.5 - d) / (c.r + 1.5) * 1.8;
          mx += (ddx / d) * f;
          mz += (ddz / d) * f;
        }
      }
      const len = Math.hypot(mx, mz) || 1;
      mx /= len; mz /= len;
      const step = Math.min(speed * dt, dist);
      pos.x += mx * step;
      pos.z += mz * step;
      const r = Math.hypot(pos.x, pos.z);
      if (r > 116) { pos.x *= 116 / r; pos.z *= 116 / r; }
      this.effSpeed = speed;
      const targetYaw = Math.atan2(mx, mz);
      this.yaw += shortestAngle(this.yaw, targetYaw) * Math.min(1, dt * 6);
    } else {
      this.effSpeed = 0;
      if (this.state === 'lurk') {
        const targetYaw = Math.atan2(target.x - pos.x, target.z - pos.z);
        this.yaw += shortestAngle(this.yaw, targetYaw) * Math.min(1, dt * 2.5);
      }
    }
    pos.y = this.world.heightAt(pos.x, pos.z);
    this.group.rotation.y = this.yaw;
  }

  _moveAround(player, desiredDist, speed, dt) {
    this.repathTimer -= dt;
    const pos = this.group.position;
    if (this.repathTimer <= 0) {
      this.repathTimer = rand(3, 6);
      const ang = Math.atan2(pos.z - player.z, pos.x - player.x) + rand(-0.9, 0.9);
      let x = player.x + Math.cos(ang) * desiredDist;
      let z = player.z + Math.sin(ang) * desiredDist;
      const r = Math.hypot(x, z);
      if (r > 112) { x *= 112 / r; z *= 112 / r; }
      this.target.set(x, 0, z);
    }
    this._moveToward(this.target, speed, dt, 1.2);
  }

  _teleportAround(player, minD, maxD) {
    const a = rand(0, TAU), d = rand(minD, maxD);
    let x = player.x + Math.cos(a) * d, z = player.z + Math.sin(a) * d;
    const r = Math.hypot(x, z);
    if (r > 112) { x *= 112 / r; z *= 112 / r; }
    this.group.position.set(x, this.world.heightAt(x, z), z);
    this.group.scale.setScalar(1);
    this.spawnScale = 1;
    this.stateTime = 0;
  }

  _catch(p) {
    this.caught = true;
    this.state = 'caught';
    this.stateTime = 0;
    this.events.push({ type: 'catch' });
    // snap in front of the player -- the scare rig takes it from here
    this.group.position.set(p.x, this.world.heightAt(p.x, p.z), p.z);
    this.group.rotation.y = Math.atan2(p.x - this.group.position.x, p.z - this.group.position.z);
  }

  _animate(dt, player, camera, speed, facePlayer) {
    const t = performance.now() / 1000;
    const moving = speed > 0.1;
    this.legPhase += dt * (moving ? speed * 1.55 : 0.4);

    const amp = this.state === 'hunt' ? 0.72 : this.state === 'retreat' ? 0.55 : moving ? 0.34 : 0.05;
    this.legs.forEach((leg, i) => {
      const phase = this.legPhase + (i === 0 || i === 3 ? 0 : Math.PI);
      const swing = Math.sin(phase) * amp;
      leg.hip.rotation.x = leg.base + swing + (this.state === 'hunt' ? 0.1 : 0);
      leg.knee.rotation.x = 0.55 + Math.max(0, Math.sin(phase + 1.1)) * amp * 1.1;
      leg.hip.rotation.z = (leg.def.x < 0 ? 1 : -1) * 0.03;
    });

    // body bob
    const bob = moving ? Math.sin(this.legPhase * 2) * (this.state === 'hunt' ? 0.1 : 0.05) : Math.sin(t * 1.4) * 0.02;
    this.body.position.y = 2.35 + bob;
    this.chest.position.y = 2.45 + bob;
    this.headRig.position.y = 3.32 + bob * 0.7;

    // breathing
    const breath = 1 + Math.sin(t * 1.7) * 0.012;
    this.chest.scale.set(0.78 * breath, 0.72 * breath, 0.9);

    // head track player
    if (facePlayer && camera && this.state !== 'retreat' && this.state !== 'caught') {
      const headWorld = new THREE.Vector3();
      this.headRig.getWorldPosition(headWorld);
      const dir = new THREE.Vector3().subVectors(camera.position, headWorld);
      const local = this.headRig.parent.worldToLocal(headWorld.clone().add(dir));
      const yaw = Math.atan2(local.x, local.z);
      const pitch = Math.atan2(local.y - 0.1, Math.hypot(local.x, local.z));
      this.headRig.rotation.y = lerp(this.headRig.rotation.y, clamp(yaw, -0.85, 0.85), 1 - Math.exp(-4 * dt));
      this.headRig.rotation.x = lerp(this.headRig.rotation.x, clamp(-pitch, -0.5, 0.6), 1 - Math.exp(-4 * dt));
    } else {
      this.headRig.rotation.y = lerp(this.headRig.rotation.y, 0, 1 - Math.exp(-3 * dt));
      this.headRig.rotation.x = lerp(this.headRig.rotation.x, 0, 1 - Math.exp(-3 * dt));
    }

    // jaw — breathing, snarl when hunting
    const jawOpen = this.state === 'hunt'
      ? 0.16 + Math.max(0, Math.sin(t * 2.6)) * 0.18
      : this.state === 'caught' ? 0.9 : 0.03 + Math.max(0, Math.sin(t * 1.2)) * 0.05;
    this.jaw.rotation.x = lerp(this.jaw.rotation.x, jawOpen, 1 - Math.exp(-6 * dt));

    // tail sway
    this.tail.forEach((seg, i) => {
      seg.rotation.y = Math.sin(t * 1.2 + i * 0.6) * 0.12;
      seg.rotation.x = (i === 0 ? 0.35 : 0.04) + Math.sin(t * 0.9 + i) * 0.03;
    });

    // ears
    this.head.userData.ears.forEach((ear, i) => {
      ear.rotation.z = (i === 0 ? 1 : -1) * (0.35 + Math.sin(t * 0.7 + i) * 0.04);
    });

    // eyes: blink (rare), flare in hunt
    this.blinkTimer -= dt;
    let blink = 1;
    if (this.blinkTimer < 0) {
      const k = (-this.blinkTimer) / 0.14;
      blink = k < 1 ? Math.abs(Math.cos(k * Math.PI)) : 1;
      if (-this.blinkTimer > 0.16) this.blinkTimer = rand(3, 7);
    }
    const eyePower = this.state === 'hunt' ? 1.25 : 0.85;
    this.head.userData.eyes.forEach(e => { e.scale.y = 0.9 * blink; });
    this.eyeSprites.forEach(s => {
      s.scale.setScalar((this.state === 'hunt' ? 0.9 : 0.62) * (0.8 + Math.sin(t * 3.1) * 0.1));
      s.material.opacity = clamp(eyePower * (1.1 - this.distToPlayer / 55), 0.25, 1);
    });

    // heavy footsteps
    if (moving) {
      this.stepDist += this.effSpeed * dt;
      if (this.stepDist > (this.state === 'hunt' || this.state === 'retreat' ? 2.2 : 3.0)) {
        this.stepDist = 0;
        this.events.push({ type: 'step' });
      }
    }

    this.group.updateMatrixWorld();
  }
}

/* ==================================================================
   JUMPSCARE — a mouth, very close, briefly
   ================================================================== */
export class Jumpscare {
  constructor(camera, audio) {
    this.camera = camera;
    this.audio = audio;
    this.rig = new THREE.Group();
    this.rig.visible = false;
    camera.add(this.rig);
    this.head = buildWolfHead({ scare: true });
    this.head.scale.setScalar(1.1);
    this.rig.add(this.head);
    this.head.userData.jaw.rotation.x = 0.05;

    this.light = new THREE.PointLight('#e8f4cc', 6, 4, 2);
    this.light.position.set(0.2, 0.4, 0.5);
    this.rig.add(this.light);
    const red = new THREE.PointLight('#8a0d06', 9, 3.5, 2);
    red.position.set(-0.5, -0.2, -0.2);
    this.rig.add(red);

    // wet eye reflections
    this.sprites = [];
    for (const s of [-1, 1]) {
      const spr = new THREE.Sprite(new THREE.SpriteMaterial({
        map: glowTexture(), color: '#f2ffcc', transparent: true, opacity: 1,
        blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false, fog: false
      }));
      spr.position.set(s * 0.29, 0.22, 0.84);
      spr.scale.setScalar(0.36);
      this.head.add(spr);
      this.sprites.push(spr);
    }

    this.active = false;
    this.t = 0;
    this.duration = 2.0;
    this.short = false;
  }

  show(short = false) {
    this.active = true;
    this.short = short;
    this.t = 0;
    this.duration = short ? 0.85 : 2.1;
    this.rig.visible = true;
    this.rig.position.set(0, 0, 0);
    this.rig.rotation.set(0, 0, 0);
    this.head.rotation.set(0, 0, 0);
    this.head.position.set(0, 0, -2.8);
    this.head.userData.jaw.rotation.x = short ? 0.5 : 0.02;
    this.audio?.jumpscare();
  }

  hide() {
    this.active = false;
    this.rig.visible = false;
  }

  update(dt, camera) {
    if (!this.active) return;
    this.t += dt;
    const t = this.t;
    const short = this.short;
    const lungeA = short ? 0.06 : 0.22;
    const holdEnd = short ? 0.55 : 1.55;

    // two-stage lunge: snap in, recoil, then fill the screen
    let z, jaw, shake;
    if (t < lungeA) {
      const k = t / lungeA;
      z = lerp(-2.8, -1.05, Math.pow(k, 0.55));
      jaw = lerp(0.4, 0.9, k);
      shake = 0.05;
    } else if (!short && t < 0.42) {
      const k = (t - lungeA) / 0.2;
      z = lerp(-1.05, -1.5, Math.sin(k * Math.PI) * 0.7);
      jaw = 0.65 + Math.sin(k * Math.PI) * 0.25;
      shake = 0.09;
    } else if (t < holdEnd) {
      z = -0.92 + Math.sin(t * 47) * 0.025;
      jaw = 0.95;
      shake = 0.10;
    } else {
      const k = clamp((t - holdEnd) / (this.duration - holdEnd), 0, 1);
      z = lerp(-0.92, -3.2, k * k);
      jaw = 0.95 * (1 - k * 0.3);
      shake = 0.05;
    }

    this.head.position.z = z;
    this.head.position.x = Math.sin(t * 83) * shake * 0.25;
    this.head.position.y = Math.cos(t * 67) * shake * 0.18;
    this.head.rotation.z = Math.sin(t * 41) * shake * 0.3;
    this.head.rotation.y = Math.sin(t * 29) * shake * 0.22;
    this.head.userData.jaw.rotation.x = lerp(this.head.userData.jaw.rotation.x, jaw, 1 - Math.exp(-20 * dt));

    const flare = 0.32 + Math.sin(t * 37) * 0.06;
    this.sprites.forEach(s => s.scale.setScalar(flare));
    this.light.intensity = 6 + Math.sin(t * 61) * 2;

    // camera shake and FOV punch
    if (camera) {
      const s = t < holdEnd ? 0.055 : 0.02;
      camera.rotation.z = Math.sin(t * 53) * s;
      camera.rotation.x += Math.sin(t * 79) * s * 0.35;
      camera.rotation.y += Math.cos(t * 61) * s * 0.35;
    }

    if (t >= this.duration) {
      this.hide();
      if (camera) camera.rotation.z = 0;
    }
  }
}

import * as THREE from 'three';
import { clamp, damp, lerp, rand, TAU } from './util.js';

export class Player {
  constructor(camera, canvas, world, audio) {
    this.camera = camera;
    this.canvas = canvas;
    this.world = world;
    this.audio = audio;
    this.position = new THREE.Vector3(3, 0, 5);
    this.velocity = new THREE.Vector3();
    this.yaw = 0;
    this.pitch = 0;
    this.keys = new Set();
    this.enabled = false;
    this.pointerLocked = false;
    this.stamina = 100;
    this.battery = 100;
    this.torchOn = true;
    this.crouching = false;
    this.sprinting = false;
    this.moving = false;
    this.eyeHeight = 1.66;
    this.bob = 0;
    this.stepDist = 0;
    this.noise = 0;
    this.touchMove = { x: 0, y: 0 };
    this.touchSprint = false;
    this.lookSensitivity = 0.0022;
    this.sprintingLock = false;
    this._buildTorch();
    this._buildHeldTorch();
    this._bindEvents();
  }

  _buildTorch() {
    const spot = new THREE.SpotLight('#e8ecd0', 0, 46, 0.44, 0.62, 1.7);
    spot.position.set(0.14, -0.1, 0);
    this.spot = spot;
    this.camera.add(spot);
    const target = new THREE.Object3D();
    target.position.set(0, -0.12, -8);
    this.camera.add(target);
    spot.target = target;
    this.spotTarget = target;

    // faint bounce so the world isn't pitch black without the torch
    this.eyeLight = new THREE.PointLight('#4d5a4a', 0.5, 5, 2);
    this.eyeLight.position.set(0, 0.1, -0.2);
    this.camera.add(this.eyeLight);
  }

  _buildHeldTorch() {
    const g = new THREE.Group();
    const body = new THREE.Mesh(
      new THREE.CylinderGeometry(0.035, 0.045, 0.3, 8),
      new THREE.MeshStandardMaterial({ color: '#1a1c18', roughness: 0.5, metalness: 0.7 })
    );
    body.rotation.x = Math.PI / 2;
    g.add(body);
    const head = new THREE.Mesh(
      new THREE.CylinderGeometry(0.075, 0.05, 0.12, 10),
      new THREE.MeshStandardMaterial({ color: '#2a2c26', roughness: 0.35, metalness: 0.8 })
    );
    head.rotation.x = Math.PI / 2;
    head.position.z = -0.19;
    g.add(head);
    const lens = new THREE.Mesh(
      new THREE.CircleGeometry(0.062, 12),
      new THREE.MeshBasicMaterial({ color: '#fffbe0' })
    );
    lens.position.z = -0.255;
    lens.rotation.y = Math.PI;
    g.add(lens);
    this.lens = lens;
    g.position.set(0.27, -0.27, -0.48);
    g.rotation.set(0.06, -0.08, 0.03);
    this.camera.add(g);
    this.heldTorch = g;
    this.heldBase = g.position.clone();
  }

  _bindEvents() {
    const onKey = e => {
      const k = e.key.toLowerCase();
      if (['w', 'a', 's', 'd', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright', 'shift', 'control', 'f', 'q', 'e', ' '].includes(k)) e.preventDefault();
      if (e.type === 'keydown') {
        this.keys.add(k);
        if (k === 'f') this.toggleTorch();
        if (k === 'shift') this.sprintingLock = true;
        if (k === 'control') this.crouching = true;
      } else {
        this.keys.delete(k);
        if (k === 'shift') this.sprintingLock = false;
        if (k === 'control') this.crouching = false;
      }
    };
    window.addEventListener('keydown', onKey);
    window.addEventListener('keyup', onKey);

    const mouse = e => {
      if (!this.enabled) return;
      if (document.pointerLockElement === this.canvas) {
        this.addLook(e.movementX, e.movementY);
      }
    };
    document.addEventListener('mousemove', mouse);

    this.canvas.addEventListener('click', () => {
      if (this.enabled && !this.isTouch) this.requestLock();
    });

    document.addEventListener('pointerlockchange', () => {
      this.pointerLocked = document.pointerLockElement === this.canvas;
    });

    window.addEventListener('blur', () => {
      this.keys.clear();
      this.sprintingLock = false;
    });
  }

  get isTouch() {
    return window.matchMedia('(hover: none)').matches || 'ontouchstart' in window;
  }

  requestLock() {
    if (this.isTouch) return;
    try { this.canvas.requestPointerLock?.(); } catch { /* ignore */ }
  }

  look(dx, dy) { this.addLook(dx, dy); }

  addLook(dx, dy) {
    const s = this.lookSensitivity * (this.zoomed ? 0.6 : 1);
    this.yaw -= dx * s;
    this.pitch -= dy * s;
    this.pitch = clamp(this.pitch, -1.25, 1.25);
  }

  toggleTorch(force) {
    if (!this.enabled && force === undefined) return;
    const next = force === undefined ? !this.torchOn : force;
    if (next && this.battery < 4) {
      this.audio?.scuff();
      return;
    }
    this.torchOn = next;
  }

  setPose(x, z, yaw = 0, pitch = 0) {
    this.position.set(x, this.world.heightAt(x, z), z);
    this.yaw = yaw; this.pitch = pitch;
    this.syncCamera(0);
  }

  syncCamera(dt) {
    const eye = this.crouching ? 1.12 : this.eyeHeight;
    const speed = this.velocity.length();
    const bobAmt = this.moving ? Math.min(1, speed / 4) : 0;
    this.bob += dt * (this.sprinting ? 11 : 7.5);
    const bx = Math.sin(this.bob) * 0.022 * bobAmt;
    const by = Math.abs(Math.cos(this.bob)) * 0.035 * bobAmt;

    this.camera.position.set(
      this.position.x + bx * Math.cos(this.yaw),
      this.position.y + eye + by,
      this.position.z - bx * Math.sin(this.yaw)
    );
    const roll = Math.sin(this.bob) * 0.008 * bobAmt;
    this.camera.rotation.set(this.pitch, this.yaw, roll, 'YXZ');

    // held torch sway
    if (this.heldTorch) {
      this.heldTorch.position.x = this.heldBase.x + bx * 0.6;
      this.heldTorch.position.y = this.heldBase.y - by * 0.5;
      this.heldTorch.visible = this.torchOn;
      this.lens.material.color.set(this.torchOn ? '#fffbe0' : '#33342c');
    }
  }

  update(dt) {
    if (!this.enabled) {
      this.syncCamera(dt);
      return;
    }
    const k = this.keys;
    let ix = 0, iz = 0;
    if (k.has('w') || k.has('arrowup')) iz -= 1;
    if (k.has('s') || k.has('arrowdown')) iz += 1;
    if (k.has('a') || k.has('arrowleft')) ix -= 1;
    if (k.has('d') || k.has('arrowright')) ix += 1;

    // touch stick
    if (Math.abs(this.touchMove.x) > 0.01 || Math.abs(this.touchMove.y) > 0.01) {
      ix += this.touchMove.x;
      iz += this.touchMove.y;
    }
    const len = Math.hypot(ix, iz);
    if (len > 1) { ix /= len; iz /= len; }

    const wantSprint = (this.sprintingLock || this.touchSprint) && this.stamina > 1 && !this.crouching && len > 0.1;
    this.sprinting = wantSprint;
    const baseSpeed = this.crouching ? 1.55 : 2.85;
    const targetSpeed = this.sprinting ? 5.45 : baseSpeed;

    // stamina
    if (this.sprinting) {
      this.stamina = Math.max(0, this.stamina - 19 * dt);
    } else {
      this.stamina = Math.min(100, this.stamina + (this.moving ? 8 : 15) * dt);
    }

    // torch battery
    if (this.torchOn) {
      this.battery = Math.max(0, this.battery - 1.85 * dt);
      if (this.battery <= 0) this.torchOn = false;
    } else {
      this.battery = Math.min(100, this.battery + 1.2 * dt);
    }

    const forward = new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
    const right = new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
    const wish = new THREE.Vector3()
      .addScaledVector(forward, -iz)
      .addScaledVector(right, ix);
    if (wish.lengthSq() > 0) wish.normalize();

    const accel = 12;
    this.velocity.x = damp(this.velocity.x, wish.x * targetSpeed, accel, dt);
    this.velocity.z = damp(this.velocity.z, wish.z * targetSpeed, accel, dt);
    if (wish.lengthSq() < 0.01) {
      this.velocity.x = damp(this.velocity.x, 0, 10, dt);
      this.velocity.z = damp(this.velocity.z, 0, 10, dt);
    }

    this.position.x += this.velocity.x * dt;
    this.position.z += this.velocity.z * dt;
    this.world.resolveCollision(this.position, 0.36);
    this.position.y = this.world.heightAt(this.position.x, this.position.z);

    const speed = Math.hypot(this.velocity.x, this.velocity.z);
    this.moving = speed > 0.35;
    this.noise = this.moving ? (this.sprinting ? 1 : this.crouching ? 0.12 : 0.4) : 0.06;

    // footsteps
    if (this.moving) {
      this.stepDist += speed * dt;
      const stride = this.sprinting ? 2.4 : this.crouching ? 1.35 : 1.85;
      if (this.stepDist > stride) {
        this.stepDist = 0;
        this.audio?.step(this.sprinting);
      }
    }

    // torch flicker when low / hunted
    const low = this.battery < 22;
    let intensity = this.torchOn ? 5.2 : 0;
    if (this.torchOn && low) {
      const flick = Math.sin(performance.now() * 0.043) * Math.sin(performance.now() * 0.011);
      intensity *= flick > 0.55 ? 0.25 : 0.9;
      this.lens.material.color.set(flick > 0.55 ? '#6a6a58' : '#fffbe0');
    }
    this.spot.intensity = lerp(this.spot.intensity, intensity, 1 - Math.exp(-8 * dt));
    this.spot.angle = 0.46;
    this.spot.distance = 48;
    this.spot.color.set('#e9edd3');

    this.syncCamera(dt);
  }

  /** Returns a 0..1 threat estimate based on torch flicker proximity etc. */
  get torchLit() { return this.torchOn && this.spot.intensity > 0.4; }
}

