    this.target = new THREE.Vector3();
    this.eyeGlow = glowTexture();
    this.distToPlayer = 99;
    this.pan = 0;
    this.legPhase = 0;
    this.blinkTimer = 3;

      }
    }

    this.group.updateMatrixWorld();
