    this.head.rotation.y = Math.sin(t * 31) * shake * 0.4;
    this.head.rotation.x = Math.sin(t * 67) * shake * 0.25;
    this.jaw.rotation.x = lerp(this.jaw.rotation.x, jaw, 1 - Math.exp(-22 * dt));
