const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const fs = require('fs');
const path = require('path');
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';

(async () => {
  const cfg = JSON.parse(fs.readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
  process.env.DISPLAY ||= ':' + fs.readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim();
  const browser = await chromium.launch({ ...cfg.browser.launchOptions });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(1500);
  await page.evaluate(() => document.getElementById('btn-play').click());
  await page.waitForTimeout(250);
  await page.evaluate(() => { window.__hollow.G.introT = 11.55; });
  await page.waitForTimeout(500);
  await page.evaluate(() => { window.__hollow.G.wakeT = 5.4; });
  await page.waitForTimeout(800);
  console.log('mode', await page.evaluate(() => window.__hollow.G.mode));

  // keep the wolf away while we walk the whole loop
  await page.evaluate(() => {
    const h = window.__hollow;
    h.wolf.group.visible = false;
    h.wolf.spawnGrace = 9999;
    h.wolf.state = 'lurk';
    h.wolf.pressure = 0;
    h.player.torchOn = true;
    h.player.battery = 100;
  });

  // collect all twenty by walking onto each marker
  const picked = await page.evaluate(async () => {
    const h = window.__hollow;
    const wait = (ms) => new Promise(r => setTimeout(r, ms));
    for (const part of h.world.parts) {
      if (part.taken) continue;
      h.player.position.set(part.x, h.world.heightAt(part.x, part.z), part.z + 0.4);
      h.player.velocity.set(0, 0, 0);
      h.player.syncCamera(0.016);
      await wait(130);
    }
    return {
      pieces: h.G.pieces,
      finalPhase: h.G.finalPhase,
      beacon: !!(h.world.beacon && h.world.beacon.visible),
      objective: document.getElementById('objective')?.textContent
    };
  });
  console.log('collect', picked);
  await page.waitForTimeout(500);
  await page.screenshot({ path: path.join(out, 'e2e-allparts.png') });

  // return to the wreck
  await page.evaluate(() => {
    const h = window.__hollow;
    h.player.position.set(3.4, h.world.heightAt(3.4, 3.4), 3.4);
    h.player.syncCamera(0.016);
  });
  await page.waitForTimeout(700);
  console.log('mode repair?', await page.evaluate(() => window.__hollow.G.mode));
  await page.screenshot({ path: path.join(out, 'e2e-repair.png') });

  await page.evaluate(() => { window.__hollow.G.repairT = 3.0; });
  await page.waitForTimeout(500);
  await page.screenshot({ path: path.join(out, 'e2e-repair-wolf.png') });

  await page.evaluate(() => { window.__hollow.G.repairT = 7.25; });
  await page.waitForTimeout(900);
  console.log('ending', await page.evaluate(() => window.__hollow.G.mode),
    await page.evaluate(() => getComputedStyle(document.getElementById('ending')).display));
  await page.screenshot({ path: path.join(out, 'e2e-ending.png') });

  // death screen + retry from a fresh run
  await page.evaluate(() => {
    const h = window.__hollow;
    h.G.mode = 'play';
    h.G.pieces = 4;
    h.G.scareT = 0;
    h.G.scareBlack = false;
    h.wolf.group.visible = false;
    h.wolf._catch(h.player.position);
  });
  await page.waitForTimeout(300);
  await page.screenshot({ path: path.join(out, 'e2e-scare-live.png') });
  await page.evaluate(() => { window.__hollow.G.scareT = 2.14; });
  await page.waitForTimeout(600);
  console.log('dead', await page.evaluate(() => window.__hollow.G.mode),
    await page.evaluate(() => getComputedStyle(document.getElementById('dead')).display));
  await page.screenshot({ path: path.join(out, 'e2e-dead.png') });
  await page.evaluate(() => document.getElementById('btn-retry')?.click());
  await page.waitForTimeout(700);
  console.log('retry', await page.evaluate(() => window.__hollow.G.mode), 'pieces', await page.evaluate(() => window.__hollow.G.pieces));

  console.log('errors', errors);
  await browser.close();
})();

