const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const fs = require('fs');
const path = require('path');
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';

(async () => {
  const cfg = JSON.parse(fs.readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
  process.env.DISPLAY ||= ':' + fs.readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim();
  const browser = await chromium.launch({ ...cfg.browser.launchOptions });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
  page.on('pageerror', e => console.log('PAGEERROR', e.message));
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(1400);
  const info = await page.evaluate(() => {
    document.getElementById('title').style.display = 'none';
    document.getElementById('fx-black').style.opacity = '0';
    const j = window.__hollow.jumpscare;
    j.show(false);
    j.update(0.65);
    j.update = function () { this.t = 0.65; };
    const palette = [0xff00ff, 0x00ffff, 0x00ff00, 0x0000ff, 0xffff00, 0xff8800, 0x8800ff, 0xffffff];
    const rows = [];
    let i = 0;
    j.head.traverse(o => {
      if (!o.isMesh || !o.material || !o.material.color) return;
      const g = o.geometry;
      const p = g.parameters || {};
      const c = o.material.color.getHex();
      // recolour the mouth-region meshes only
      if (o.position.y < 0.02 && o.position.z > 0.5) {
        o.material = o.material.clone();
        o.material.color.setHex(palette[i % palette.length]);
        o.material.emissive?.setHex(0x000000);
        rows.push({
          color: '#' + palette[i % palette.length].toString(16).padStart(6, '0'),
          geo: g.type, params: p, pos: [o.position.x, o.position.y, o.position.z].map(v => +v.toFixed(2))
        });
        i++;
      }
    });
    window.__hollow.renderer.render(j.scene, j.camera);
    return rows;
  });
  console.log(JSON.stringify(info, null, 1));
  await page.waitForTimeout(300);
  await page.screenshot({ path: path.join(out, 'diag-mouth-colors.png') });
  await browser.close();
})();

